/* ---------- Afrique : pays et régions encore peu servis ---------- */
const D55 = [
{ id:'suya', c:'af', lat:9.058, lon:7.492, base:4, prep:40, cook:15, diff:2, tags:['beef','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f2e6c8',style:'skewer',food:['#8f3b2a','#c9754a','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Suya',en:'Suya'},
  p:{fr:'Abuja, Nigeria',en:'Abuja, Nigeria'},
  d:{fr:"Des lanières de bœuf enrobées de yaji, une poudre d'arachide et d'épices, grillées sur la braise. Les mallams haoussas les vendent le soir sur des claies ; le yaji se remet après cuisson, jamais seulement avant.",
     en:"Strips of beef coated in yaji, a groundnut and spice powder, grilled over coals. Hausa mallams sell them at night from wooden racks; the yaji goes on again after grilling, never only before."},
  i:[['beef_sirloin',800,'g'],['peanuts',200,'g'],['ginger',40,'g'],['smoked_paprika',2,'tbsp'],['cayenne',2,'tbsp'],['garlic_powder',1,'tbsp'],['onion_powder',1,'tbsp'],['bouillon_cube',2,'pc'],['peanut_oil',80,'ml'],['onion',2,'pc'],['ripe_tomato',2,'pc'],['cabbage',200,'g'],['salt',null,'']],
  s:{fr:["Grillez les arachides à sec, frottez-les entre les mains pour ôter les peaux, puis moulez-les.","Pressez la poudre dans un linge pour en retirer l'huile : trop grasse, elle ne colle pas à la viande.","Mêlez-la au paprika, au cayenne, au gingembre, à l'ail, à l'oignon en poudre et au cube émietté : c'est le yaji.","Taillez le bœuf en lanières très fines, enfilez-les en accordéon sur des brochettes, huilez et roulez dans le yaji.","Grillez 6 minutes en tournant, puis saupoudrez à nouveau de yaji à la sortie. Servez avec oignon cru, tomate et chou."],
     en:["Dry-roast the peanuts, rub off the skins between your hands, then grind them.","Press the powder in a cloth to squeeze out the oil: too oily, it will not cling to the meat.","Mix it with the paprika, cayenne, ginger, garlic and onion powder and the crumbled stock cube: this is yaji.","Cut the beef into very thin strips, thread them concertina-style on skewers, oil and roll in the yaji.","Grill for 6 minutes, turning, then dust with yaji again as it comes off. Serve with raw onion, tomato and cabbage."]} },

{ id:'attieke-poisson', c:'af', lat:5.320, lon:-4.017, base:4, prep:30, cook:30, diff:2, tags:['sea','grill','street'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e8dcc0','#c9402c','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Attiéké poisson braisé',en:'Attiéké with grilled fish'},
  p:{fr:'Abidjan, Côte d’Ivoire',en:'Abidjan, Ivory Coast'},
  d:{fr:"De la semoule de manioc fermentée, servie avec un poisson braisé et une sauce claire à l'oignon. L'attiéké se reconnaît à son acidité : c'est la fermentation du manioc, et c'est elle qui répond au poisson gras.",
     en:"Fermented cassava semolina, served with grilled fish and a sharp onion relish. Attiéké is known by its sourness: that is the cassava fermenting, and it answers the oily fish."},
  i:[['attieke',600,'g'],['whole_fish',1.5,'kg'],['onion',4,'pc'],['ripe_tomato',400,'g'],['scotch_bonnet',2,'pc'],['ginger',50,'g'],['garlic',6,'clove'],['lemon',3,'pc'],['peanut_oil',100,'ml'],['bouillon_cube',1,'pc'],['cucumber',1,'pc'],['parsley',1,'bunch'],['salt',null,'']],
  s:{fr:["Écaillez et videz le poisson, entaillez-le trois fois de chaque côté et frottez-le au citron et au sel.","Pilez ail, gingembre, un oignon, le piment et le cube, et poussez la pâte dans les entailles et dans le ventre.","Laissez mariner une heure, puis grillez sur braises modérées 15 minutes par face, en badigeonnant d'huile.","Passez l'attiéké à la vapeur 15 minutes et égrenez-le à la fourchette pour l'aérer.","Préparez la sauce claire : oignons émincés, tomate, piment et citron, sans cuisson. Servez le tout ensemble."],
     en:["Scale and gut the fish, score it three times each side and rub it with lemon and salt.","Pound the garlic, ginger, one onion, the chilli and the stock cube, and push the paste into the cuts and the belly.","Marinate for an hour, then grill over moderate coals 15 minutes a side, basting with oil.","Steam the attiéké for 15 minutes and fluff it with a fork to separate the grains.","Make the raw relish: sliced onion, tomato, chilli and lemon, uncooked. Serve everything together."]} },

{ id:'poulet-moambe', c:'af', lat:-4.322, lon:15.307, base:6, prep:30, cook:90, diff:2, tags:['poultry','slow','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#c9754a','#e0913a','#4f6f3a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Poulet à la moambe',en:'Chicken moambe'},
  p:{fr:'Kinshasa, RD Congo',en:'Kinshasa, DR Congo'},
  d:{fr:"Du poulet mijoté dans la pulpe de noix de palme, avec des feuilles de manioc à part. C'est le plat national des deux Congo ; on le mange avec les doigts et du chikwangue, la pâte de manioc en bâton.",
     en:"Chicken stewed in palm nut pulp, with cassava leaves alongside. It is the national dish of both Congos; eaten with the fingers and chikwangue, the cassava paste in its wrapper."},
  i:[['chicken',1.6,'kg'],['palm_nut_pulp',500,'g'],['palm_oil',80,'ml'],['onion',3,'pc'],['garlic',8,'clove'],['ginger',50,'g'],['ripe_tomato',300,'g'],['scotch_bonnet',2,'pc'],['cassava_leaves',500,'g'],['peanut_butter',80,'g'],['long_grain_rice',500,'g'],['bouillon_cube',2,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet 2 heures dans l'ail, le gingembre pilés et le citron.","Délayez la pulpe de noix de palme dans un litre d'eau chaude et passez-la au tamis pour retirer les fibres.","Faites colorer le poulet à l'huile de palme, ajoutez l'oignon et la tomate, puis versez le jus de palme.","Laissez mijoter 50 minutes à découvert : l'huile orange doit remonter franchement à la surface.","Cuisez à part les feuilles de manioc pilées 1 heure avec l'arachide. Servez les deux côte à côte, avec du riz."],
     en:["Marinate the chicken for 2 hours in pounded garlic and ginger with lemon.","Slake the palm nut pulp in a litre of hot water and pass it through a sieve to remove the fibres.","Colour the chicken in palm oil, add the onion and tomato, then pour in the palm juice.","Simmer uncovered for 50 minutes: the orange oil must rise clearly to the surface.","Separately cook the pounded cassava leaves for 1 hour with the groundnut. Serve the two side by side, with rice."]} },

{ id:'djenkoume', c:'af', lat:6.137, lon:1.212, base:6, prep:35, cook:60, diff:2, tags:['poultry','comfort','festive'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'cake',food:['#c9402c','#e0913a','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Djenkoumé',en:'Djenkoumé'},
  p:{fr:'Lomé, Togo',en:'Lomé, Togo'},
  d:{fr:"Une galette de farine de maïs cuite dans une sauce tomate, coupée en carrés et servie avec du poulet. Elle se démoule comme un gâteau et se mange à la main : le Togo en fait le plat des dimanches et des baptêmes.",
     en:"A maize flour cake cooked in tomato sauce, cut into squares and served with chicken. It turns out like a cake and is eaten by hand: Togo makes it the dish of Sundays and christenings."},
  i:[['corn_flour',500,'g'],['chicken',1.4,'kg'],['ripe_tomato',700,'g'],['onion',4,'pc'],['scotch_bonnet',2,'pc'],['garlic',8,'clove'],['ginger',50,'g'],['peanut_oil',150,'ml'],['tomato_paste',3,'tbsp'],['bouillon_cube',2,'pc'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet à l'ail, au gingembre et au cube, puis faites-le frire jusqu'à ce qu'il dore.","Dans la même huile, faites revenir l'oignon et le concentré, puis ajoutez la tomate mixée et le piment.","Laissez réduire 25 minutes : la sauce doit être très concentrée, presque une pâte.","Prélevez les deux tiers de la sauce, allongez-les d'eau bouillante et versez-y la farine de maïs en pluie.","Travaillez 20 minutes jusqu'à ce que la pâte se détache, versez dans un moule huilé, laissez prendre et coupez en carrés."],
     en:["Marinate the chicken in garlic, ginger and stock cube, then fry it until golden.","In the same oil, fry the onion and tomato paste, then add the blended tomato and chilli.","Reduce for 25 minutes: the sauce should be very concentrated, almost a paste.","Take out two thirds of the sauce, let it down with boiling water and rain in the maize flour.","Work for 20 minutes until the paste leaves the sides, turn into an oiled tin, let it set and cut into squares."]} },

{ id:'riz-gras-guineen', c:'af', lat:9.641, lon:-13.578, base:6, prep:35, cook:75, diff:2, tags:['rice','sea','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'rice',food:['#e0913a','#c9402c','#4f6f3a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Riz gras guinéen',en:'Guinean riz gras'},
  p:{fr:'Conakry, Guinée',en:'Conakry, Guinea'},
  d:{fr:"Un riz cuit dans un bouillon de poisson fumé, de tomate et de feuilles de patate douce. La Guinée fume son poisson sur des claies de bois : c'est cette fumée, plus que la tomate, qui donne au riz son goût.",
     en:"Rice cooked in a broth of smoked fish, tomato and sweet potato leaves. Guinea smokes its fish on wooden racks: it is that smoke, more than the tomato, that flavours the rice."},
  i:[['long_grain_rice',600,'g'],['smoked_fish',300,'g'],['grouper',600,'g'],['tomato_paste',4,'tbsp'],['ripe_tomato',400,'g'],['onion',3,'pc'],['sweet_potato_leaves',400,'g'],['okra',200,'g'],['scotch_bonnet',2,'pc'],['peanut_oil',150,'ml'],['garlic',6,'clove'],['bouillon_cube',2,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper le poisson fumé 20 minutes à l'eau chaude, puis effeuillez-le en retirant les arêtes.","Faites frire le concentré de tomate dans l'huile 8 minutes, jusqu'à ce que l'huile rougisse.","Ajoutez l'oignon, l'ail, la tomate fraîche et le poisson fumé, et laissez réduire 20 minutes.","Mouillez de deux litres d'eau, ajoutez les feuilles, les gombos et le piment entier, et cuisez 25 minutes.","Retirez les légumes, versez le riz dans le bouillon restant et laissez-le l'absorber 25 minutes à couvert."],
     en:["Soak the smoked fish for 20 minutes in hot water, then flake it, removing the bones.","Fry the tomato paste in the oil for 8 minutes, until the oil turns red.","Add the onion, garlic, fresh tomato and smoked fish, and reduce for 20 minutes.","Add two litres of water, the leaves, okra and whole chilli, and cook for 25 minutes.","Lift out the vegetables, pour the rice into the remaining broth and let it absorb for 25 minutes, covered."]} },

{ id:'cachupa-rica', c:'af', lat:14.917, lon:-23.508, base:8, prep:40, cook:180, diff:2, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e8c46a','#8f5a3a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Cachupa rica',en:'Cachupa rica'},
  p:{fr:'Praia, Santiago, Cap-Vert',en:'Praia, Santiago, Cape Verde'},
  d:{fr:"Un ragoût de maïs concassé, de haricots et de toutes les viandes disponibles, mijoté une demi-journée. Le lendemain, on la fait sauter à la poêle avec un œuf : c'est la cachupa guisada, et beaucoup la préfèrent.",
     en:"A stew of cracked maize, beans and every available meat, simmered half a day. The next day it is fried with an egg: cachupa guisada, and many prefer it that way."},
  i:[['hominy_corn',500,'g'],['white_beans',250,'g'],['red_kidney_beans',150,'g'],['pork_belly',400,'g'],['chourico',200,'g'],['beef_chuck',300,'g'],['cabbage',400,'g'],['cassava',400,'g'],['sweet_potato',400,'g'],['pumpkin',400,'g'],['onion',3,'pc'],['garlic',8,'clove'],['bay_leaf',3,'pc'],['olive_oil',100,'ml'],['egg',6,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper le maïs et les haricots séparément une nuit entière : le maïs concassé demande douze heures.","Cuisez le maïs 1 h 30 dans une grande marmite, puis ajoutez les haricots pour 45 minutes.","Ajoutez les viandes en gros morceaux, l'oignon, l'ail et le laurier, et laissez mijoter 1 heure.","Ajoutez les tubercules et la courge par ordre de fermeté, puis le chou pour les 20 dernières minutes.","Écrasez un peu de courge contre la paroi pour lier. Le lendemain, faites-la revenir à la poêle avec un œuf au plat."],
     en:["Soak the maize and beans separately overnight: cracked maize needs twelve hours.","Cook the maize for 1½ hours in a large pot, then add the beans for 45 minutes.","Add the meats in large pieces, the onion, garlic and bay, and simmer for 1 hour.","Add the roots and squash in order of firmness, then the cabbage for the last 20 minutes.","Crush a little squash against the side to thicken. Next day, fry it in a pan with a fried egg."]} },

{ id:'thiebou-yapp', c:'af', lat:16.026, lon:-16.489, base:8, prep:45, cook:90, diff:2, tags:['sea','rice','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'rice',food:['#f0e8d0','#e8c46a','#7fae5a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Thiébou yapp',en:'Thiébou yapp'},
  p:{fr:'Nouakchott, Mauritanie',en:'Nouakchott, Mauritania'},
  d:{fr:"Le riz à la viande du fleuve Sénégal, brun de tomate et d'oignon confit, sans poisson. On le sert dans un plat unique posé au sol, et chacun mange dans le quartier de riz qui lui fait face.",
     en:"The meat rice of the Senegal River, browned with tomato and long-cooked onion, without fish. It is served in a single dish set on the ground, each person eating from the quarter facing them."},
  i:[['lamb_shoulder',1.2,'kg'],['broken_rice',700,'g'],['onion',800,'g'],['tomato_paste',4,'tbsp'],['ripe_tomato',400,'g'],['carrot',3,'pc'],['cabbage',400,'g'],['cassava',400,'g'],['scotch_bonnet',2,'pc'],['garlic',8,'clove'],['peanut_oil',180,'ml'],['bouillon_cube',2,'pc'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites colorer l'agneau en gros morceaux dans l'huile, puis retirez-le.","Faites fondre les oignons en lamelles dans la même huile, 40 minutes, jusqu'à ce qu'ils brunissent : c'est eux qui donnent la couleur.","Ajoutez le concentré et laissez-le foncer, puis la tomate, l'ail et deux litres d'eau.","Remettez la viande et laissez mijoter 50 minutes, puis ajoutez les légumes par ordre de fermeté et retirez-les cuits.","Versez le riz lavé dans le bouillon restant, couvrez et laissez-le l'absorber 25 minutes à feu très doux."],
     en:["Colour the lamb in large pieces in the oil, then lift it out.","Melt the sliced onions in the same oil for 40 minutes, until they brown: they give the colour.","Add the tomato paste and let it darken, then the fresh tomato, garlic and two litres of water.","Return the meat and simmer for 50 minutes, then add the vegetables in order of firmness and remove each when done.","Pour the washed rice into the remaining broth, cover and let it absorb for 25 minutes over very low heat."]} },

{ id:'riz-au-gras-burkinabe', c:'af', lat:12.371, lon:-1.520, base:6, prep:30, cook:70, diff:1, tags:['poultry','rice','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'rice',food:['#c9402c','#e0913a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Riz gras burkinabè',en:'Burkinabè riz gras'},
  p:{fr:'Ouagadougou, Burkina Faso',en:'Ouagadougou, Burkina Faso'},
  d:{fr:"Un riz mijoté dans un bouillon de tomate et de viande, cuit dans une seule marmite. C'est le plat des maquis et des cérémonies ; le riz doit rester ferme et chaque grain garder sa couleur.",
     en:"Rice simmered in a tomato and meat broth, cooked in a single pot. It is the dish of the maquis bars and of ceremonies; the rice must stay firm and each grain keep its colour."},
  i:[['long_grain_rice',600,'g'],['chicken',1.2,'kg'],['tomato_paste',4,'tbsp'],['ripe_tomato',500,'g'],['onion',3,'pc'],['garlic',6,'clove'],['ginger',40,'g'],['scotch_bonnet',2,'pc'],['carrot',3,'pc'],['cabbage',300,'g'],['peanut_oil',150,'ml'],['bouillon_cube',2,'pc'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet à l'ail, au gingembre et au cube émietté pendant une heure.","Faites-le colorer dans l'huile, retirez-le, et faites frire le concentré de tomate 8 minutes dans la même huile.","Ajoutez l'oignon, la tomate mixée et le piment entier, et laissez réduire 20 minutes.","Mouillez de trois litres d'eau, remettez le poulet et cuisez 30 minutes, puis ajoutez carotte et chou.","Retirez viande et légumes, versez le riz lavé et laissez-le absorber le bouillon 25 minutes à couvert."],
     en:["Marinate the chicken in garlic, ginger and crumbled stock cube for an hour.","Colour it in the oil, lift it out, and fry the tomato paste for 8 minutes in the same oil.","Add the onion, blended tomato and whole chilli, and reduce for 20 minutes.","Add three litres of water, return the chicken and cook for 30 minutes, then add the carrot and cabbage.","Lift out the meat and vegetables, pour in the washed rice and let it absorb the broth for 25 minutes, covered."]} },

{ id:'kilishi', c:'af', lat:13.512, lon:2.113, base:8, prep:120, cook:20, diff:3, tags:['beef','slow','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f2e6c8',style:'grill',food:['#8f3b2a','#6f4a2a','#c9754a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Kilishi',en:'Kilishi'},
  p:{fr:'Niamey, Niger',en:'Niamey, Niger'},
  d:{fr:"Des feuilles de bœuf séchées au soleil, enduites de pâte d'arachide épicée, puis grillées. La viande est tranchée si finement qu'on peut lire au travers : un seul kilo de bœuf donne moins de trois cents grammes de kilishi.",
     en:"Sheets of beef sun-dried, coated in spiced groundnut paste, then grilled. The meat is sliced so thin you can read through it: a kilo of beef yields under three hundred grams of kilishi."},
  i:[['beef_round',1,'kg'],['peanuts',300,'g'],['ginger',60,'g'],['garlic',10,'clove'],['cayenne',3,'tbsp'],['onion_powder',2,'tbsp'],['cloves',1,'tsp'],['bouillon_cube',2,'pc'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Taillez le bœuf en feuilles de 2 mm dans le sens de la fibre : le couteau doit être long et parfaitement affûté.","Étalez-les sur des claies et faites-les sécher au soleil 6 heures, en les retournant, jusqu'à ce qu'elles durcissent.","Moulez les arachides grillées et mêlez-les à l'eau, au gingembre, à l'ail, au cayenne et au cube, en une pâte liquide.","Trempez chaque feuille dans cette pâte et remettez-la à sécher 3 heures, jusqu'à ce que l'enrobage prenne.","Grillez-les 4 minutes sur braises douces, en surveillant : l'arachide brûle en quelques secondes."],
     en:["Cut the beef into 2 mm sheets along the grain: the knife must be long and perfectly sharp.","Spread them on racks and sun-dry for 6 hours, turning, until they stiffen.","Grind the roasted peanuts and mix them with water, ginger, garlic, cayenne and stock cube into a thin paste.","Dip each sheet in the paste and return it to dry for 3 hours, until the coating sets.","Grill for 4 minutes over gentle coals, watching closely: groundnut burns in seconds."]} },

{ id:'kanyah-liberien', c:'af', lat:6.301, lon:-10.797, base:8, prep:25, cook:15, diff:1, tags:['sweet','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e0b45a','#8f6a4a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Kanyah',en:'Kanyah'},
  p:{fr:'Monrovia, Liberia',en:'Monrovia, Liberia'},
  d:{fr:"Une barre de riz grillé, d'arachide et de sucre, pressée à la main et coupée en carrés. C'est la ration de voyage libérienne : elle ne demande aucune cuisson, tient une semaine, et cale un homme jusqu'au soir.",
     en:"A bar of toasted rice, groundnut and sugar, pressed by hand and cut into squares. It is the Liberian travelling ration: no cooking, keeps a week, and sees a man through to evening."},
  i:[['long_grain_rice',400,'g'],['peanuts',400,'g'],['sugar',200,'g'],['peanut_oil',60,'ml'],['nutmeg',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites griller le riz cru à sec dans une poêle épaisse, en remuant sans arrêt, jusqu'à ce qu'il brunisse et éclate.","Faites griller les arachides séparément et frottez-les entre les mains pour ôter les peaux.","Moulez le riz grillé très finement, puis les arachides, jusqu'à obtenir une poudre grasse.","Mêlez les deux au sucre, à la muscade et au sel, et ajoutez l'huile cuillère par cuillère jusqu'à ce que la masse tienne.","Pressez fermement dans un moule plat, laissez raffermir une heure et coupez en carrés."],
     en:["Dry-toast the raw rice in a heavy pan, stirring constantly, until it browns and pops.","Roast the peanuts separately and rub off the skins between your hands.","Grind the toasted rice very finely, then the peanuts, into an oily powder.","Mix the two with the sugar, nutmeg and salt, and add the oil a spoonful at a time until the mass holds together.","Press firmly into a flat mould, let it firm for an hour and cut into squares."]} },

{ id:'gozo-sauce-koko', c:'af', lat:4.395, lon:18.558, base:6, prep:30, cook:75, diff:2, tags:['veg','comfort','slow'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#4f6f3a','#e0913a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Gozo et sauce koko',en:'Gozo with koko sauce'},
  p:{fr:'Bangui, République centrafricaine',en:'Bangui, Central African Republic'},
  d:{fr:"Une pâte de manioc accompagnée d'une sauce de feuilles de koko, de viande fumée et d'arachide. La feuille de koko est une liane forestière que l'on ne cultive pas : elle se ramasse, et son émincé est un art.",
     en:"A cassava paste with a sauce of koko leaves, smoked meat and groundnut. The koko leaf is a forest vine that is never cultivated: it is gathered, and slicing it is an art."},
  i:[['cassava_flour',500,'g'],['koko_leaves',600,'g'],['peanut_butter',200,'g'],['smoked_fish',250,'g'],['palm_oil',150,'ml'],['onion',2,'pc'],['garlic',6,'clove'],['scotch_bonnet',2,'pc'],['dried_shrimp',60,'g'],['bouillon_cube',2,'pc'],['salt',null,'']],
  s:{fr:["Émincez les feuilles de koko en lanières de la finesse d'un cheveu : c'est long, et c'est ce qui fait la texture de la sauce.","Faites tremper le poisson fumé, effeuillez-le et retirez toutes les arêtes.","Faites chauffer l'huile de palme, ajoutez l'oignon, l'ail et le piment, puis les feuilles et un demi-litre d'eau.","Laissez mijoter 40 minutes : les feuilles doivent perdre leur amertume sans devenir noires.","Délayez l'arachide et incorporez-la avec le poisson pour 20 minutes. Servez avec le gozo, la pâte de manioc travaillée à l'eau bouillante."],
     en:["Slice the koko leaves into hair-fine ribbons: it takes time, and it makes the texture of the sauce.","Soak the smoked fish, flake it and remove every bone.","Heat the palm oil, add the onion, garlic and chilli, then the leaves and half a litre of water.","Simmer for 40 minutes: the leaves should lose their bitterness without turning black.","Slake the groundnut and stir it in with the fish for 20 minutes. Serve with gozo, the cassava paste worked with boiling water."]} },

{ id:'haricots-bananes-vertes', c:'af', lat:-3.383, lon:29.360, base:6, prep:30, cook:75, diff:1, tags:['legume','comfort','slow'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#c9754a','#4f6f3a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Haricots aux bananes vertes',en:'Beans with green banana'},
  p:{fr:'Bujumbura, Burundi',en:'Bujumbura, Burundi'},
  d:{fr:"Des haricots rouges mijotés avec des bananes plantain vertes et de l'huile de palme. C'est le repas quotidien des collines burundaises : le haricot pour la force, la banane pour tenir jusqu'au soir.",
     en:"Red beans stewed with green plantains and palm oil. It is the daily meal of the Burundian hills: the bean for strength, the banana to last until evening."},
  i:[['red_kidney_beans',500,'g'],['green_plantain',6,'pc'],['palm_oil',120,'ml'],['onion',3,'pc'],['ripe_tomato',400,'g'],['garlic',6,'clove'],['celery',3,'stalk'],['leek',1,'pc'],['scotch_bonnet',1,'pc'],['bouillon_cube',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit, puis cuisez-les 1 heure dans une eau non salée.","Épluchez les bananes vertes sous l'eau — leur sève tache durablement les mains — et coupez-les en tronçons.","Faites revenir l'oignon, l'ail, le poireau et le céleri dans l'huile de palme, ajoutez la tomate.","Versez ce sofrito sur les haricots avec leur eau, ajoutez les bananes et le piment entier.","Laissez mijoter 40 minutes : les bananes doivent devenir fondantes et le bouillon épaissir de lui-même."],
     en:["Soak the beans overnight, then cook them for 1 hour in unsalted water.","Peel the green plantains under water — their sap stains the hands lastingly — and cut them into lengths.","Fry the onion, garlic, leek and celery in palm oil, and add the tomato.","Pour this sofrito over the beans with their liquid, add the plantains and the whole chilli.","Simmer for 40 minutes: the plantains should turn meltingly soft and the broth thicken by itself."]} },

{ id:'matapa', c:'af', lat:-25.966, lon:32.567, base:6, prep:30, cook:60, diff:2, tags:['sea','comfort','slow'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#2f4f2a','#f0e8d0','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Matapa',en:'Matapa'},
  p:{fr:'Maputo, Mozambique',en:'Maputo, Mozambique'},
  d:{fr:"Des feuilles de manioc pilées au lait de coco, avec crabe et crevettes, servies sur du riz. Le Mozambique pile la feuille avec l'arachide dans le même mortier : les deux se fondent et la sauce en devient verte et grasse.",
     en:"Cassava leaves pounded with coconut milk, with crab and prawns, served over rice. Mozambique pounds the leaf and the groundnut in the same mortar: the two merge and the sauce turns green and rich."},
  i:[['cassava_leaves',700,'g'],['coconut_milk',700,'ml'],['peanuts',200,'g'],['crab_meat',300,'g'],['shrimp',400,'g'],['garlic',8,'clove'],['onion',2,'pc'],['piri_piri',2,'pc'],['long_grain_rice',500,'g'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Pilez les feuilles de manioc et les arachides ensemble, longuement, jusqu'à obtenir une pâte grossière.","Faites-les blanchir 20 minutes à grande eau et pressez-les : la feuille crue est toxique, la cuisson longue est obligatoire.","Faites revenir l'oignon et l'ail à l'huile, ajoutez la pâte pressée et un demi-litre d'eau.","Laissez mijoter 30 minutes, puis versez le lait de coco et poursuivez 15 minutes sans bouillir.","Ajoutez le crabe et les crevettes pour les 8 dernières minutes seulement. Servez avec du riz blanc."],
     en:["Pound the cassava leaves and peanuts together, at length, into a coarse paste.","Blanch them for 20 minutes in plenty of water and squeeze them dry: the raw leaf is toxic, and long cooking is compulsory.","Fry the onion and garlic in oil, add the pressed paste and half a litre of water.","Simmer for 30 minutes, then pour in the coconut milk and continue for 15 minutes without boiling.","Add the crab and prawns for the last 8 minutes only. Serve with white rice."]} },

{ id:'potjie-de-gibier', c:'af', lat:-22.560, lon:17.083, base:8, prep:30, cook:180, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Potjie de gibier',en:'Game potjie'},
  p:{fr:'Windhoek, Namibie',en:'Windhoek, Namibia'},
  d:{fr:"Un ragoût d'oryx ou de koudou cuit en couches dans une marmite à trois pieds, sur les braises. La Namibie mange le gibier comme d'autres le bœuf : la viande est maigre, et le lard qu'on ajoute n'est pas un luxe.",
     en:"An oryx or kudu stew cooked in layers in a three-legged pot over embers. Namibia eats game as others eat beef: the meat is lean, and the bacon added to it is not a luxury."},
  i:[['venison',1.5,'kg'],['smoked_bacon',250,'g'],['onion',3,'pc'],['red_wine',400,'ml'],['beef_stock',400,'ml'],['carrot',400,'g'],['potato',600,'g'],['pumpkin',400,'g'],['juniper_berries',10,'pc'],['bay_leaf',3,'pc'],['brown_sugar',1,'tbsp'],['peanut_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le gibier 12 heures dans le vin rouge avec le genièvre et le laurier : la marinade attendrit et adoucit le goût de venaison.","Faites fondre le lard au fond de la marmite posée sur des braises modérées, puis saisissez la viande égouttée.","Ajoutez l'oignon, la marinade filtrée et le fond, et laissez mijoter 2 heures à couvert.","Disposez les légumes en couches distinctes, du plus long au plus court, et ne remuez plus jamais.","Laissez encore 1 heure. On sert en creusant depuis le bord, pour garder les étages visibles."],
     en:["Marinate the game for 12 hours in red wine with juniper and bay: the marinade tenderises and softens the venison note.","Render the bacon in the pot set over moderate embers, then sear the drained meat.","Add the onion, strained marinade and stock, and simmer covered for 2 hours.","Arrange the vegetables in distinct layers, longest-cooking first, and never stir again.","Give it another hour. Serve by digging in from the edge, to keep the tiers visible."]} },

{ id:'papa-ea-poone', c:'af', lat:-29.316, lon:27.483, base:6, prep:25, cook:60, diff:1, tags:['veg','comfort','slow'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4f0e6',style:'stew',food:['#f4f0e6','#e8c46a','#7fae5a','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Papa ea poone',en:'Papa ea poone'},
  p:{fr:'Maseru, Lesotho',en:'Maseru, Lesotho'},
  d:{fr:"Une pâte de maïs frais râpé, cuite lentement, servie avec du moroho, les feuilles vertes du jardin. Le Lesotho la fait avec le maïs de la récolte, encore laiteux : elle est alors sucrée sans qu'on ajoute rien.",
     en:"A paste of freshly grated maize, cooked slowly, served with moroho, the greens from the garden. Lesotho makes it with harvest maize, still milky: it is sweet without anything being added."},
  i:[['corn_cobs',10,'pc'],['white_cornmeal',200,'g'],['mustard_greens',600,'g'],['onion',2,'pc'],['tomato',300,'g'],['butter',60,'g'],['whole_milk',200,'ml'],['peanut_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les grains de maïs frais sur une râpe à gros trous, en recueillant le lait qui s'en échappe.","Faites-les cuire à feu doux avec le lait recueilli 25 minutes, en remuant : la masse épaissit d'elle-même.","Ajoutez la farine de maïs en pluie pour raffermir, et travaillez 15 minutes de plus au bâton.","Pour le moroho, faites tomber les feuilles avec l'oignon et la tomate, à couvert, 20 minutes.","Servez la pâte en dôme, creusée d'un puits de beurre, avec les feuilles à côté."],
     en:["Grate the fresh maize kernels on a coarse grater, catching the milk that runs from them.","Cook them gently with the collected milk for 25 minutes, stirring: the mass thickens by itself.","Rain in the maize flour to firm it up, and work for another 15 minutes with a stick.","For the moroho, wilt the greens with the onion and tomato, covered, for 20 minutes.","Serve the paste as a dome, hollowed into a well of butter, with the greens alongside."]} },

{ id:'sishwala', c:'af', lat:-26.317, lon:31.133, base:6, prep:20, cook:75, diff:1, tags:['poultry','comfort','slow'],
  art:{v:'plate',bg:'#33301f',plate:'#f4f0e6',style:'stew',food:['#f4f0e6','#e0b45a','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sishwala et poulet',en:'Sishwala with chicken'},
  p:{fr:'Mbabane, Eswatini',en:'Mbabane, Eswatini'},
  d:{fr:"Une bouillie de maïs épaisse, plus dense que le pap, servie avec un poulet de basse-cour mijoté. Le sishwala se coupe au couteau une fois refroidi : c'est ce qui le distingue des autres pâtes de la région.",
     en:"A maize porridge thicker than pap, served with a stewed farmyard chicken. Sishwala can be cut with a knife once cool: that is what sets it apart from the region's other pastes."},
  i:[['white_cornmeal',500,'g'],['chicken',1.6,'kg'],['onion',3,'pc'],['ripe_tomato',400,'g'],['peanut_oil',80,'ml'],['bouillon_cube',2,'pc'],['pumpkin_leaves',400,'g'],['peanuts',100,'g'],['garlic',4,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites colorer le poulet découpé dans l'huile, puis ajoutez l'oignon et l'ail.","Ajoutez la tomate concassée et le cube émietté, mouillez à peine et laissez mijoter 50 minutes à couvert.","Portez un litre et demi d'eau salée à ébullition et versez la farine de maïs en pluie en fouettant.","Travaillez 30 minutes à feu doux au bâton de bois : le sishwala doit être plus ferme qu'un pap ordinaire.","Servez la pâte moulée dans un bol mouillé, avec le poulet et des feuilles de courge à l'arachide."],
     en:["Colour the jointed chicken in the oil, then add the onion and garlic.","Add the crushed tomato and crumbled stock cube, barely moisten and simmer covered for 50 minutes.","Bring a litre and a half of salted water to the boil and rain in the maize flour, whisking.","Work it for 30 minutes over low heat with a wooden stick: sishwala should be firmer than an ordinary pap.","Serve the paste moulded in a wetted bowl, with the chicken and pumpkin leaves in groundnut."]} },

{ id:'cari-poisson-seychellois', c:'af', lat:-4.679, lon:55.492, base:4, prep:30, cook:40, diff:2, tags:['sea','comfort','spicy'],
  art:{v:'pot',bg:'#26384a',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#f0e8d0','#c9402c','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Cari de poisson au coco',en:'Coconut fish curry'},
  p:{fr:'Victoria, Mahé, Seychelles',en:'Victoria, Mahé, Seychelles'},
  d:{fr:"Un cari de poisson de récif au lait de coco frais, au curcuma et aux feuilles de curry. Les Seychelles râpent la noix sur un tabouret à lame, le grajeur : le lait pressé à la main n'a pas le goût de la boîte.",
     en:"A reef fish curry with fresh coconut milk, turmeric and curry leaves. Seychelles grate the nut on a bladed stool, the grajeur: hand-pressed milk tastes nothing like the tin."},
  i:[['red_snapper',1,'kg'],['coconut_milk',600,'ml'],['onion',3,'pc'],['garlic',8,'clove'],['ginger',50,'g'],['turmeric',2,'tsp'],['curry_leaves',15,'pc'],['cinnamon',1,'pc'],['ripe_tomato',300,'g'],['bird_eye_chili',3,'pc'],['lime',3,'pc'],['peanut_oil',80,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Taillez le poisson en darnes épaisses et frottez-les de curcuma, de sel et de citron vert ; laissez 20 minutes.","Faites revenir l'oignon, l'ail et le gingembre pilés dans l'huile avec les feuilles de curry et la cannelle.","Ajoutez la tomate et le reste du curcuma, et laissez réduire 10 minutes.","Versez le lait de coco et portez à frémissement, sans jamais bouillir : il tournerait.","Glissez les darnes et laissez pocher 12 minutes à découvert, en arrosant. Citron vert au dernier moment."],
     en:["Cut the fish into thick steaks and rub them with turmeric, salt and lime; leave 20 minutes.","Fry the pounded onion, garlic and ginger in oil with the curry leaves and cinnamon.","Add the tomato and the remaining turmeric, and reduce for 10 minutes.","Pour in the coconut milk and bring to a bare simmer, never boiling: it would split.","Slide in the steaks and poach for 12 minutes uncovered, basting. Lime at the last moment."]} },

{ id:'vindaye-de-poisson', c:'af', lat:-20.164, lon:57.502, base:4, prep:25, cook:45, diff:1, tags:['sea','comfort','spicy'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#c9402c','#e0913a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Vindaye de poisson',en:'Vindaye fish'},
  p:{fr:'Port-Louis, Maurice',en:'Port Louis, Mauritius'},
  d:{fr:"Du poisson frit mariné au curcuma, à la moutarde et au vinaigre, mangé froid. Le vindaye descend du vindaloo goanais ; à Maurice il se conserve une semaine et se bonifie chaque jour.",
     en:"Fried fish marinated in turmeric, mustard and vinegar, eaten cold. Vindaye descends from Goan vindaloo; in Mauritius it keeps a week and improves daily."},
  i:[['tuna',800,'g'],['turmeric',2,'tbsp'],['mustard_seeds',3,'tbsp'],['garlic',10,'clove'],['ginger',60,'g'],['white_wine_vinegar',200,'ml'],['onion',3,'pc'],['bird_eye_chili',4,'pc'],['peanut_oil',150,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Taillez le thon en tranches épaisses, frottez-les de curcuma et de sel, et faites-les frire jusqu'à ce qu'elles colorent.","Écrasez les graines de moutarde au mortier avec l'ail, le gingembre et un peu de vinaigre.","Faites revenir cette pâte dans l'huile 8 minutes, sans la laisser brûler : la moutarde deviendrait amère.","Ajoutez l'oignon en lamelles et les piments fendus, et laissez-les à peine tomber : ils doivent rester croquants.","Versez le reste du vinaigre, laissez tiédir, puis noyez le poisson dedans. Attendez 24 heures avant de servir, froid."],
     en:["Cut the tuna into thick slices, rub them with turmeric and salt, and fry them until coloured.","Crush the mustard seeds in a mortar with the garlic, ginger and a little vinegar.","Fry this paste in the oil for 8 minutes, without letting it burn: the mustard would turn bitter.","Add the sliced onion and split chillies, and barely wilt them: they should stay crunchy.","Pour in the rest of the vinegar, let it cool, then submerge the fish in it. Wait 24 hours and serve cold."]} },

{ id:'langouste-a-la-vanille', c:'af', lat:-11.702, lon:43.254, base:4, prep:30, cook:30, diff:2, tags:['sea','festive','fresh'],
  art:{v:'plate',bg:'#26384a',plate:'#f4ecd8',style:'fish',food:['#c9402c','#f0a878','#e8c46a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Langouste à la vanille',en:'Lobster with vanilla'},
  p:{fr:'Moroni, Comores',en:'Moroni, Comoros'},
  d:{fr:"De la langouste au lait de coco parfumée à la vanille des Comores. L'archipel produit l'ylang-ylang et la vanille ; le mariage de la gousse et du crustacé est une idée d'île, et elle fonctionne.",
     en:"Lobster in coconut milk scented with Comoran vanilla. The islands grow ylang-ylang and vanilla; pairing the pod with shellfish is an island idea, and it works."},
  i:[['lobster',2,'kg'],['vanilla',2,'pc'],['coconut_milk',500,'ml'],['shallot',4,'pc'],['garlic',6,'clove'],['ginger',40,'g'],['lime',3,'pc'],['butter',80,'g'],['white_wine',150,'ml'],['bird_eye_chili',1,'pc'],['long_grain_rice',400,'g'],['cilantro',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Fendez les langoustes vivantes en deux dans la longueur, d'un coup net, et retirez la poche à graviers.","Saisissez-les chair vers le bas dans le beurre mousseux, 4 minutes, puis retirez-les.","Faites suer l'échalote, l'ail et le gingembre, déglacez au vin blanc et laissez réduire de moitié.","Ajoutez le lait de coco et les gousses de vanille fendues et grattées, et laissez infuser 10 minutes à frémissement.","Remettez les langoustes carapace vers le bas et laissez cuire 8 minutes en arrosant. Citron vert et coriandre à la fin."],
     en:["Split the live lobsters lengthways in one clean stroke, and remove the grit sac.","Sear them flesh down in foaming butter for 4 minutes, then lift them out.","Sweat the shallot, garlic and ginger, deglaze with white wine and reduce by half.","Add the coconut milk and the split, scraped vanilla pods, and infuse for 10 minutes at a simmer.","Return the lobsters shell down and cook for 8 minutes, basting. Lime and coriander at the end."]} },

{ id:'oladii', c:'eu', lat:55.755, lon:37.617, base:4, prep:40, cook:20, diff:1, tags:['sweet','breakfast','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9402c','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Oladii',en:'Oladii'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"De petites crêpes épaisses au kéfir, plus hautes et plus moelleuses que le blini, servies au petit-déjeuner avec de la confiture. Le kéfir doit être franchement acide : c'est son acidité qui réagit avec le bicarbonate et fait gonfler la pâte, sans levure ni attente.",
     en:"Small thick pancakes made with kefir, taller and softer than blini, served at breakfast with jam. The kefir must be frankly sour: its acidity reacts with the bicarbonate and lifts the batter, with no yeast and no waiting."},
  i:[['kefir',250,'ml'],['flour',200,'g'],['egg',1,'pc'],['sugar',2,'tbsp'],['baking_soda',1,'tsp'],['sunflower_oil',80,'ml'],['apricot_jam',200,'g'],['smetana',150,'g'],['salt',null,'']],
  s:{fr:["Sortez le kéfir une heure à l'avance : froid, il ne réagit pas au bicarbonate et les oladii restent plats.","Battez l'œuf, le sucre et le sel dans le kéfir, puis versez la farine tamisée d'un coup et mêlez en une vingtaine de tours seulement.","Ajoutez le bicarbonate en dernier et ne remuez plus du tout : les bulles se forment aussitôt, et remuer les chasse.","Laissez reposer dix minutes sans y toucher — la surface doit se couvrir de cratères — puis prélevez à la cuillère sans mélanger le fond.","Cuisez dans un centimètre d'huile chaude, 2 minutes par face. Servez avec la confiture d'abricot et la smetana."],
     en:["Take the kefir out an hour ahead: cold, it does not react with the bicarbonate and the oladii stay flat.","Beat the egg, sugar and salt into the kefir, then tip in the sifted flour all at once and mix in twenty turns only.","Add the bicarbonate last and stop stirring altogether: the bubbles form at once, and stirring drives them out.","Rest ten minutes untouched — the surface should crater — then spoon it out without disturbing the bottom.","Cook in a centimetre of hot oil, 2 minutes a side. Serve with apricot jam and smetana."]} },

{ id:'pirog-au-chou', c:'eu', lat:56.419, lon:40.449, base:8, prep:150, cook:50, diff:2, tags:['veg','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#7fae5a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pirog au chou',en:'Cabbage pirog'},
  p:{fr:'Souzdal, Russie',en:'Suzdal, Russia'},
  d:{fr:"Une grande tourte briochée au chou fondu et à l'œuf dur, coupée en carrés et servie aux fêtes. Dans le Nord on y cachait une pièce pour désigner qui aurait de la chance dans l'année ; le chou doit être longuement fondu, sans quoi il rend son eau et détrempe la pâte.",
     en:"A large brioche pie of melted cabbage and hard-boiled egg, cut into squares and served at feasts. In the north a coin was hidden inside to mark who would be lucky that year; the cabbage must be long melted, or it weeps and soaks the dough."},
  i:[['flour',600,'g'],['whole_milk',250,'ml'],['fresh_yeast',20,'g'],['butter',100,'g'],['egg',4,'pc'],['green_cabbage',900,'g'],['onion',2,'pc'],['dill',1,'bunch'],['sugar',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez une pâte briochée avec la farine, le lait tiède, la levure, un œuf, le beurre et le sel, et laissez lever 1 h 30.","Émincez le chou très finement et faites-le fondre 40 minutes à la poêle avec l'oignon, à couvert d'abord puis à découvert.","Il doit avoir perdu les trois quarts de son volume et ne plus rendre une goutte : c'est là toute la réussite du pirog.","Laissez-le refroidir complètement, puis ajoutez trois œufs durs hachés et l'aneth.","Foncez un moule, garnissez, couvrez d'une seconde abaisse, soudez en pinçant, dorez et cuisez 50 minutes à 180 °C. Se mange tiède, coupé en carrés."],
     en:["Knead a brioche dough with the flour, warm milk, yeast, one egg, the butter and salt, and prove for 1½ hours.","Slice the cabbage very finely and melt it in a pan for 40 minutes with the onion, covered at first then uncovered.","It must have lost three-quarters of its volume and stopped weeping altogether: that is the whole success of a pirog.","Cool it completely, then add three chopped hard-boiled eggs and the dill.","Line a tin, fill, cover with a second sheet, seal by pinching, glaze and bake 50 minutes at 180°C. Eaten warm, cut into squares."]} },

{ id:'koulibiak-royal', c:'eu', lat:59.940, lon:30.316, base:8, prep:180, cook:55, diff:3, tags:['sea','festive','bake'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#e0a8a0','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Koulibiak royal',en:'Royal koulibiak'},
  p:{fr:'Saint-Pétersbourg, Russie',en:'Saint Petersburg, Russia'},
  d:{fr:"Un pâté en croûte à étages : saumon, riz, champignons et œufs, séparés par de fines crêpes. Les crêpes ne sont pas un ornement : elles absorbent l'humidité de chaque couche et empêchent le feuilletage du fond de rester cru, et Escoffier les a gardées en l'important à Paris.",
     en:"A layered pie: salmon, rice, mushrooms and egg, separated by thin pancakes. The pancakes are no ornament: they absorb the moisture of each layer and stop the base pastry staying raw, and Escoffier kept them when he took it to Paris."},
  i:[['puff_pastry',700,'g'],['salmon',700,'g'],['long_grain_rice',200,'g'],['button_mushrooms',300,'g'],['egg',5,'pc'],['flour',80,'g'],['whole_milk',200,'ml'],['butter',120,'g'],['shallot',3,'pc'],['dill',1,'bunch'],['lemon',1,'pc'],['smetana',100,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites trois crêpes très fines avec la farine, le lait et un œuf, et laissez-les refroidir à plat sur un linge.","Faites dessécher les champignons hachés à la poêle 20 minutes avec l'échalote, jusqu'à ce qu'ils ne grésillent plus.","Cuisez le riz, faites durcir deux œufs, taillez le saumon en pavés et laissez tout refroidir complètement.","Montez sur la pâte : crêpe, riz, saumon, champignons, œufs hachés, crêpe, en pressant chaque couche et en salant à chaque étage.","Refermez, soudez, dorez, ménagez deux cheminées et cuisez 20 minutes à 210 °C puis 35 minutes à 170 °C. Reposez 15 minutes avant de trancher."],
     en:["Make three very thin pancakes with the flour, milk and one egg, and cool them flat on a cloth.","Dry out the chopped mushrooms in a pan for 20 minutes with the shallot, until they stop sizzling.","Cook the rice, hard-boil two eggs, cut the salmon into slabs and let everything cool completely.","Build on the pastry: pancake, rice, salmon, mushrooms, chopped egg, pancake, pressing each layer and salting at every stage.","Close, seal, glaze, cut two chimneys and bake 20 minutes at 210°C then 35 minutes at 170°C. Rest 15 minutes before slicing."]} },

{ id:'chebureki', c:'eu', lat:43.318, lon:45.694, base:6, prep:70, cook:20, diff:2, tags:['lamb','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Chebureki',en:'Chebureki'},
  p:{fr:'Grozny, Tchétchénie, Russie',en:'Grozny, Chechnya, Russia'},
  d:{fr:"De grands chaussons d'agneau frits dans l'huile bouillante, à la pâte cloquée de bulles. La farce contient du bouillon figé qui fond à la cuisson : le premier coup de dent libère un jus brûlant, et l'on tient toujours le tcheburek penché vers le bas.",
     en:"Large lamb turnovers fried in boiling oil, their dough blistered with bubbles. The filling holds set broth that melts as it cooks: the first bite releases scalding juice, and a chebureki is always held tilted downward."},
  i:[['ground_lamb',300,'g'],['flour',400,'g'],['onion',2,'pc'],['water',150,'ml'],['beef_broth',100,'ml'],['sunflower_oil',1,'l'],['vodka',1,'tbsp'],['black_peppercorns',1,'tbsp'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, l'eau glacée, le sel et une cuillerée de vodka en une pâte ferme : la vodka s'évapore à la friture et c'est elle qui fait les cloques.","Laissez reposer la pâte 1 heure, enveloppée, pour qu'elle s'étire sans se rétracter.","Hachez l'oignon très finement — presque en purée — et mêlez-le à l'agneau et au bouillon froid pris en gelée.","Abaissez des disques de 20 cm à 1 mm, étalez une fine couche de farce sur une moitié seulement, et soudez en pressant à la fourchette en chassant tout l'air.","Frites 3 minutes à 190 °C en arrosant le dessus à la louche : la pâte doit se couvrir de grosses bulles brunes. Mangez brûlant, penché vers l'assiette."],
     en:["Knead the flour, iced water, salt and a spoonful of vodka into a firm dough: the vodka boils off in the fryer and is what makes the blisters.","Rest the dough for an hour, wrapped, so it stretches without shrinking back.","Chop the onion very finely — almost to a purée — and mix it with the lamb and the cold broth set to a jelly.","Roll 20 cm discs to 1 mm, spread a thin layer of filling on one half only, and seal with a fork, expelling all the air.","Fry 3 minutes at 190°C, ladling oil over the top: the dough must blister into large brown bubbles. Eat scalding, tilted over the plate."]} },

{ id:'belyashi', c:'eu', lat:55.796, lon:49.106, base:6, prep:150, cook:25, diff:2, tags:['beef','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#8f5a3a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Belyashi',en:'Belyashi'},
  p:{fr:'Kazan, Tatarstan, Russie',en:'Kazan, Tatarstan, Russia'},
  d:{fr:"De petits pains levés ouverts au centre, farcis de viande et frits à la poêle, trou vers le bas d'abord. Le trou n'est pas décoratif : il laisse la vapeur s'échapper au lieu de faire éclater la pâte, et il se referme à moitié en cuisant.",
     en:"Small yeasted buns open at the centre, filled with meat and pan-fried, hole down first. The hole is not decorative: it lets steam escape instead of bursting the dough, and it half closes as it cooks."},
  i:[['flour',500,'g'],['whole_milk',250,'ml'],['fresh_yeast',15,'g'],['ground_beef',200,'g'],['ground_lamb',150,'g'],['onion',2,'pc'],['egg',1,'pc'],['sunflower_oil',400,'ml'],['sugar',1,'tbsp'],['black_peppercorns',1,'tsp'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée souple avec la farine, le lait tiède, la levure, l'œuf, le sucre et le sel, et laissez lever 1 h 30.","Mêlez les viandes hachées à l'oignon râpé et à deux cuillerées d'eau glacée : cette eau devient le jus, et sans elle la farce reste sèche.","Ne faites pas revenir la farce : elle entre crue et cuit dans le pain, c'est ce qui distingue un belyash d'un simple beignet fourré.","Aplatissez des boules de 60 g, garnissez, ramenez les bords vers le centre en plis et laissez un trou du diamètre d'un doigt.","Faites-les frire dans deux centimètres d'huile à 165 °C, trou vers le bas 4 minutes, puis retournez-les 4 minutes. Feu doux : la viande crue doit cuire avant que la pâte ne brunisse."],
     en:["Knead a soft yeasted dough with the flour, warm milk, yeast, egg, sugar and salt, and prove for 1½ hours.","Mix the minced meats with grated onion and two spoonfuls of iced water: that water becomes the juice, and without it the filling stays dry.","Do not pre-cook the filling: it goes in raw and cooks inside the bun, which is what separates a belyash from an ordinary filled fritter.","Flatten 60 g balls, fill them, gather the edges to the centre in pleats and leave a hole a finger wide.","Fry in two centimetres of oil at 165°C, hole down for 4 minutes, then turn for 4 more. Low heat: the raw meat must cook before the dough browns."]} },

{ id:'echpochmak', c:'eu', lat:55.788, lon:49.122, base:6, prep:120, cook:60, diff:2, tags:['beef','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Echpochmak',en:'Echpochmak'},
  p:{fr:'Kazan, Tatarstan, Russie',en:'Kazan, Tatarstan, Russia'},
  d:{fr:"Un triangle de pâte levée farci de bœuf et de pomme de terre crus, percé au sommet pour y verser du bouillon. Le nom veut dire trois angles en tatar ; la viande et la pomme de terre entrent crues et cuisent ensemble à l'étouffée, ce qui exige une heure de four et pas moins.",
     en:"A triangle of yeasted dough filled with raw beef and potato, pierced at the top so broth can be poured in. The name means three corners in Tatar; meat and potato go in raw and cook together sealed, which needs a full hour of oven and no less."},
  i:[['flour',500,'g'],['whole_milk',200,'ml'],['fresh_yeast',15,'g'],['butter',80,'g'],['egg',2,'pc'],['beef_chuck',400,'g'],['potato',400,'g'],['onion',2,'pc'],['beef_broth',250,'ml'],['black_peppercorns',1,'tsp'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée au lait, au beurre et à un œuf, et laissez-la lever 1 h 30.","Taillez le bœuf et la pomme de terre au couteau en dés de 5 mm — hachés, ils rendraient une bouillie ; en plus gros, ils ne cuiraient pas.","Mêlez-les à l'oignon très finement haché, salez fortement et poivrez : c'est le seul assaisonnement, il doit être franc.","Découpez des disques de 15 cm, garnissez le centre et relevez trois côtés que vous soudez en triangle, en laissant un trou d'un centimètre au sommet.","Cuisez 20 minutes à 200 °C, puis versez une cuillerée de bouillon chaud par le trou et poursuivez 40 minutes à 170 °C. Répétez l'opération une fois à mi-parcours."],
     en:["Knead a yeasted dough with milk, butter and one egg, and prove it for 1½ hours.","Cut the beef and potato by knife into 5 mm dice — minced they would turn to mush; larger, they would not cook.","Mix them with very finely chopped onion, salt heavily and pepper: it is the only seasoning, and it must be forthright.","Cut 15 cm discs, fill the centre and raise three sides, sealing them into a triangle and leaving a one-centimetre hole at the top.","Bake 20 minutes at 200°C, then pour a spoonful of hot broth through the hole and continue 40 minutes at 170°C. Repeat once halfway through."]} },

{ id:'pryanik-de-toula', c:'eu', lat:54.193, lon:37.617, base:10, prep:180, cook:25, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'flat',food:['#8f6a4a','#c9924a','#f2dfa8','#e8dcb8'],garnish:'#c9754a'},
  n:{fr:'Pryanik de Toula',en:'Tula pryanik'},
  p:{fr:'Toula, Russie',en:'Tula, Russia'},
  d:{fr:"Un pain d'épices plat fourré de confiture, imprimé au moule de bois gravé. Toula fut à la fois la capitale de l'armurerie et celle du pryanik ; on l'offrait aux tsars, et il se garde trois mois en devenant progressivement plus tendre au lieu de sécher.",
     en:"A flat spice bread filled with jam and stamped from a carved wooden mould. Tula was capital both of gunsmithing and of the pryanik; it was presented to tsars, and it keeps three months, growing softer rather than drying out."},
  i:[['flour',400,'g'],['rye_flour',100,'g'],['honey',200,'g'],['sugar',100,'g'],['egg',2,'pc'],['butter',80,'g'],['cinnamon',1,'tsp'],['cloves',0.5,'tsp'],['cardamom',0.5,'tsp'],['apple_jam',250,'g'],['baking_soda',1,'tsp'],['powdered_sugar',80,'g'],['salt',null,'']],
  s:{fr:["Faites chauffer le miel et le sucre jusqu'à 110 °C, puis versez-les brûlants sur les farines mêlées aux épices, et travaillez à la cuillère.","Cette pâte ébouillantée est la clé : elle gélifie l'amidon et donne au pryanik sa souplesse durable.","Laissez-la refroidir complètement, puis incorporez les œufs, le beurre et le bicarbonate, et laissez-la reposer 12 heures au frais.","Abaissez deux plaques de 5 mm, étalez la confiture de pomme sur l'une en laissant deux centimètres de bord, et couvrez de la seconde en soudant.","Imprimez le motif au moule de bois fariné, en pressant d'un coup net et sans reprendre, et cuisez 22 minutes à 190 °C. Glacez au sucre à la sortie."],
     en:["Heat the honey and sugar to 110°C, then pour them scalding onto the flours mixed with the spices, and work with a spoon.","This scalded dough is the key: it gelatinises the starch and gives the pryanik its lasting suppleness.","Cool it completely, then work in the eggs, butter and bicarbonate, and rest it 12 hours in the cold.","Roll two 5 mm sheets, spread apple jam on one leaving a two-centimetre border, and cover with the second, sealing.","Stamp the pattern with a floured wooden mould, pressing once cleanly and never twice, and bake 22 minutes at 190°C. Glaze with sugar as it comes out."]} },

{ id:'ptichye-moloko', c:'eu', lat:55.760, lon:37.620, base:10, prep:180, cook:15, diff:3, tags:['sweet','festive','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'cake',food:['#f4f0e6','#3a2a1a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Ptitchie moloko',en:'Ptichye moloko'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Un gâteau à la mousse d'agar-agar sous une coque de chocolat noir, créé au restaurant Praga en 1968. C'est le seul gâteau soviétique à avoir été breveté ; son nom vient du lait d'oiseau, aliment introuvable des mythes antiques, et l'on faisait deux heures de queue pour en acheter.",
     en:"A cake of agar mousse under a dark chocolate shell, created at the Praga restaurant in 1968. It is the only Soviet cake to have been patented; its name comes from bird's milk, the unobtainable food of ancient myth, and people queued two hours to buy one."},
  i:[['egg_white',6,'pc'],['sugar',400,'g'],['butter',200,'g'],['condensed_milk',150,'g'],['agar_agar',4,'g'],['dark_chocolate',200,'g'],['water',150,'ml'],['flour',140,'g'],['egg_yolk',4,'pc'],['lemon',1,'pc'],['vanilla',1,'pc']],
  s:{fr:["Faites tremper l'agar-agar 1 heure dans l'eau froide, puis portez-le à ébullition avec le sucre et maintenez 2 minutes à 110 °C.","L'agar n'est pas de la gélatine : il doit bouillir pour s'activer, et il prend à 40 °C, ce qui laisse très peu de temps pour travailler.","Montez les blancs avec le jus de citron, puis versez le sirop bouillant en filet sans cesser de fouetter, et battez jusqu'à tiédir.","Incorporez le beurre pommade travaillé au lait concentré, en trois fois, à la spatule et sans attendre.","Versez sur un fond de biscuit cuit à part, lissez et laissez prendre 3 heures au froid, puis nappez de chocolat fondu tiédi à 30 °C."],
     en:["Soak the agar for an hour in cold water, then bring it to the boil with the sugar and hold it 2 minutes at 110°C.","Agar is not gelatine: it must boil to activate, and it sets at 40°C, which leaves very little time to work.","Whisk the whites with the lemon juice, then pour in the boiling syrup in a stream, whisking without pause, and beat until it cools.","Fold in the softened butter creamed with the condensed milk, in three additions, with a spatula and without delay.","Pour onto a sponge base baked separately, smooth it and set 3 hours in the cold, then coat with melted chocolate cooled to 30°C."]} },

{ id:'smetannik', c:'eu', lat:54.735, lon:55.958, base:8, prep:60, cook:40, diff:2, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'cake',food:['#f4f0e6','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Smetannik',en:'Smetannik'},
  p:{fr:'Oufa, Bachkirie, Russie',en:'Ufa, Bashkortostan, Russia'},
  d:{fr:"Un gâteau bachkir à la crème aigre, moelleux et acidulé, monté en couches fines. La smetana fait tout : sa matière grasse remplace le beurre dans la pâte et son acidité active le bicarbonate, si bien qu'aucune levure n'est nécessaire.",
     en:"A Bashkir soured-cream cake, soft and tangy, built in thin layers. The smetana does everything: its fat replaces butter in the batter and its acidity activates the bicarbonate, so no leaven is needed."},
  i:[['smetana',700,'g'],['flour',300,'g'],['sugar',300,'g'],['egg',3,'pc'],['baking_soda',1,'tsp'],['cocoa_powder',2,'tbsp'],['vanilla',1,'pc'],['walnuts',80,'g'],['salt',null,'']],
  s:{fr:["Battez 400 g de smetana avec les œufs, 150 g de sucre et le sel, puis ajoutez la farine et le bicarbonate.","Le bicarbonate mousse au contact de la smetana : versez aussitôt dans les moules, une pâte qui attend retombe.","Divisez la pâte en deux et cacaotez-en une moitié, puis cuisez quatre disques fins de 20 cm, 10 minutes chacun à 180 °C.","Fouettez la smetana restante avec le sucre restant sans jamais la monter comme une chantilly : trop battue, elle tranche et rend son petit-lait.","Montez en alternant les disques clairs et foncés, nappez le dessus et les côtés, parsemez de noix et laissez imbiber 6 heures au froid."],
     en:["Beat 400 g of the smetana with the eggs, 150 g of the sugar and the salt, then add the flour and bicarbonate.","The bicarbonate foams on meeting the smetana: pour into the tins at once, a batter that waits collapses.","Divide the batter in two and add cocoa to one half, then bake four thin 20 cm discs, 10 minutes each at 180°C.","Whisk the remaining smetana with the remaining sugar without ever whipping it like cream: overbeaten, it splits and weeps whey.","Build alternating pale and dark discs, coat the top and sides, scatter walnuts and let it soak 6 hours in the cold."]} },

{ id:'vatrushka', c:'eu', lat:55.751, lon:37.609, base:10, prep:120, cook:25, diff:2, tags:['sweet','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f4f0e6','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Vatrouchka',en:'Vatrushka'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Une galette levée creusée d'un puits de tvorog sucré, ronde comme le soleil. C'était une offrande païenne au dieu du foyer avant de devenir la pâtisserie de toutes les cantines soviétiques ; le tvorog doit être bien égoutté, sinon il gonfle et déborde du puits.",
     en:"A yeasted bun hollowed into a well of sweetened tvorog, round as the sun. It was a pagan offering to the hearth god before becoming the pastry of every Soviet canteen; the tvorog must be well drained, or it swells and overflows the well."},
  i:[['flour',500,'g'],['whole_milk',200,'ml'],['fresh_yeast',20,'g'],['butter',100,'g'],['egg',3,'pc'],['tvorog',400,'g'],['sugar',120,'g'],['vanilla',1,'pc'],['raisins',60,'g'],['semolina',1,'tbsp'],['salt',null,'']],
  s:{fr:["Égouttez le tvorog 3 heures dans un linge : c'est la seule précaution qui compte, et elle décide de tout le reste.","Pétrissez une pâte levée avec la farine, le lait tiède, la levure, un œuf, le beurre et 40 g de sucre, et laissez lever 1 h 30.","Travaillez le tvorog au tamis avec un jaune, le sucre restant, la vanille et une cuillerée de semoule, qui absorbera l'humidité résiduelle.","Façonnez des boules de 70 g, aplatissez-les et creusez le puits avec le fond d'un verre fariné, en laissant un bord de deux centimètres.","Garnissez, dorez le bord seulement, laissez pousser 30 minutes et cuisez 22 minutes à 190 °C. Le tvorog doit à peine blondir."],
     en:["Drain the tvorog 3 hours in a cloth: it is the only precaution that matters, and it decides everything else.","Knead a yeasted dough with the flour, warm milk, yeast, one egg, the butter and 40 g of the sugar, and prove 1½ hours.","Sieve the tvorog with a yolk, the remaining sugar, the vanilla and a spoonful of semolina, which will take up any residual moisture.","Shape 70 g balls, flatten them and press the well with the floured base of a glass, leaving a two-centimetre rim.","Fill, glaze the rim only, prove 30 minutes and bake 22 minutes at 190°C. The tvorog should barely colour."]} },

{ id:'koulitch', c:'eu', lat:55.752, lon:37.623, base:10, prep:420, cook:50, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f4f0e6','#c9402c','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Koulitch de Pâques',en:'Easter kulich'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Une brioche haute et étroite aux raisins, glacée de blanc et semée de vermicelles colorés, bénie à l'église le samedi saint. Elle est plus haute que large parce qu'elle imite la forme du prosphore, le pain liturgique ; on en garde un morceau séché toute l'année.",
     en:"A tall narrow raisin brioche, iced white and sprinkled with coloured strands, blessed at church on Holy Saturday. It is taller than it is wide because it imitates the prosphoron, the liturgical bread; a dried piece is kept all year."},
  i:[['flour',600,'g'],['whole_milk',200,'ml'],['fresh_yeast',30,'g'],['butter',150,'g'],['egg',5,'pc'],['sugar',180,'g'],['raisins',150,'g'],['candied_orange',80,'g'],['rum',40,'ml'],['vanilla',1,'pc'],['saffron',1,'pinch'],['powdered_sugar',150,'g'],['salt',null,'']],
  s:{fr:["Faites un levain avec la levure, le lait tiède et 150 g de farine, et laissez-le doubler 1 heure.","Ajoutez les jaunes battus au sucre, le safran infusé dans une cuillerée de lait chaud, la vanille et le sel, puis la farine restante.","Pétrissez 20 minutes avant d'incorporer le beurre mou petit à petit : cette pâte est très riche et met longtemps à devenir lisse.","Laissez lever 3 heures, incorporez les fruits macérés au rhum, emplissez les moules hauts à la moitié seulement et laissez pousser 2 heures.","Cuisez 50 minutes à 170 °C en couvrant de papier dès que le dessus colore. Laissez refroidir couché sur le côté, en tournant régulièrement, puis glacez au blanc et au sucre."],
     en:["Make a starter with the yeast, warm milk and 150 g of the flour, and let it double for an hour.","Add the yolks beaten with the sugar, the saffron infused in a spoonful of hot milk, the vanilla and salt, then the remaining flour.","Knead 20 minutes before working in the softened butter little by little: this dough is very rich and takes a long time to come smooth.","Prove 3 hours, fold in the rum-soaked fruit, fill the tall tins only halfway and prove 2 hours more.","Bake 50 minutes at 170°C, covering with paper as soon as the top colours. Cool it lying on its side, turning regularly, then ice with egg white and sugar."]} },

{ id:'kasha-grechka', c:'eu', lat:55.746, lon:37.606, base:4, prep:10, cook:30, diff:1, tags:['veg','comfort','fast'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#8f6a4a','#c9a878','#e8dcb8','#4f6f3a'],garnish:'#7fae6a'},
  n:{fr:'Kasha de sarrasin',en:'Buckwheat kasha'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Du sarrasin torréfié cuit à l'absorption, servi au beurre avec des champignons et de l'oignon. Le proverbe dit que la kasha est notre mère : c'est la base de l'alimentation de l'armée russe depuis Souvorov, et elle ne se remue jamais pendant la cuisson.",
     en:"Toasted buckwheat cooked by absorption, served with butter, mushrooms and onion. The proverb says kasha is our mother: it has been the base of the Russian army's diet since Suvorov, and it is never stirred while it cooks."},
  i:[['buckwheat_groats',300,'g'],['water',600,'ml'],['butter',60,'g'],['button_mushrooms',250,'g'],['onion',1,'pc'],['dried_mushrooms',20,'g'],['sunflower_oil',30,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites torréfier le sarrasin à sec dans la casserole 4 minutes en remuant, jusqu'à ce qu'il sente la noisette — un sarrasin non torréfié donne une kasha molle et fade.","Versez exactement deux volumes d'eau bouillante salée pour un de grain, et ne mesurez pas au jugé.","Portez à ébullition, couvrez hermétiquement et baissez au minimum : à partir de là, on ne soulève plus le couvercle et l'on ne remue plus.","Laissez 20 minutes, puis coupez le feu et laissez gonfler 10 minutes de plus, toujours couvert.","Pendant ce temps, faites revenir l'oignon et les champignons frais et secs réhydratés. Ajoutez le beurre et les champignons à la fourchette, en aérant les grains."],
     en:["Toast the buckwheat dry in the pan for 4 minutes, stirring, until it smells of hazelnuts — untoasted buckwheat gives a soft, bland kasha.","Pour in exactly two parts boiling salted water to one of grain, and do not measure by eye.","Bring to the boil, cover tightly and drop to the lowest heat: from that point the lid is not lifted and nothing is stirred.","Give it 20 minutes, then kill the heat and let it swell 10 minutes more, still covered.","Meanwhile fry the onion with the fresh mushrooms and the rehydrated dried ones. Add the butter and mushrooms with a fork, fluffing the grains."]} },

{ id:'golubtsy', c:'eu', lat:45.035, lon:38.975, base:6, prep:60, cook:90, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#7fae5a','#c9532c','#f4f0e6','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Goloubtsy',en:'Golubtsy'},
  p:{fr:'Krasnodar, Russie',en:'Krasnodar, Russia'},
  d:{fr:"Des feuilles de chou farcies de viande et de riz, mijotées dans une sauce tomate à la smetana. Golub veut dire pigeon : les rouleaux dodus rappelaient aux Russes des pigeons rôtis, plat des riches qu'ils imitaient avec du chou.",
     en:"Cabbage leaves stuffed with meat and rice, stewed in a tomato and smetana sauce. Golub means pigeon: the plump rolls reminded Russians of roast pigeon, a rich man's dish they imitated with cabbage."},
  i:[['green_cabbage',1,'pc'],['ground_beef',400,'g'],['long_grain_rice',150,'g'],['onion',2,'pc'],['carrot',2,'pc'],['tomato_puree',400,'ml'],['smetana',200,'g'],['bay_leaf',3,'pc'],['dill',1,'bunch'],['sunflower_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Retirez le trognon du chou au couteau et plongez la tête entière 10 minutes dans l'eau bouillante, en détachant les feuilles à mesure qu'elles s'assouplissent.","Aplatissez la nervure centrale de chaque feuille au rouleau ou au couteau : sans cela, elle casse au pliage et la farce s'échappe.","Cuisez le riz à moitié seulement, 7 minutes, et mêlez-le à la viande, à l'oignon et à la carotte râpés, salez fortement.","Roulez en repliant les côtés vers l'intérieur, comme un chausson, et rangez les rouleaux serrés soudure dessous dans la cocotte.","Nappez de tomate et de smetana délayées d'eau, couvrez et laissez mijoter 1 h 15 à feu très doux, sans jamais remuer."],
     en:["Cut out the cabbage core and plunge the whole head into boiling water for 10 minutes, peeling off leaves as they soften.","Flatten the central rib of each leaf with a rolling pin or knife: without that it snaps as you fold and the filling escapes.","Cook the rice only halfway, 7 minutes, and mix it with the meat and the grated onion and carrot, salting heavily.","Roll them folding the sides inward like a parcel, and pack the rolls tightly seam down in the pot.","Coat with tomato and smetana let down with water, cover and simmer 1¼ hours over very low heat, never stirring."]} },

{ id:'vinegret', c:'eu', lat:59.938, lon:30.314, base:6, prep:60, cook:40, diff:1, tags:['veg','fresh','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'salad',food:['#8f2a4a','#e0b45a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Vinegret',en:'Vinegret'},
  p:{fr:'Saint-Pétersbourg, Russie',en:'Saint Petersburg, Russia'},
  d:{fr:"Une salade d'hiver rose vif à la betterave, aux cornichons et à la choucroute, sans une trace de viande. C'était la salade du carême, la seule qu'on pouvait manger les jours maigres ; l'huile de tournesol non raffinée, qui sent la graine grillée, n'est pas remplaçable par une huile neutre.",
     en:"A bright pink winter salad of beetroot, gherkins and sauerkraut, without a trace of meat. It was the Lenten salad, the one permitted on fast days; the unrefined sunflower oil, which smells of toasted seed, cannot be swapped for a neutral one."},
  i:[['beetroot',3,'pc'],['potato',400,'g'],['carrot',2,'pc'],['pickles',4,'pc'],['sauerkraut',200,'g'],['onion',1,'pc'],['sunflower_oil',80,'ml'],['white_beans',150,'g'],['dill',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez betteraves, pommes de terre et carottes entières avec la peau, séparément : cuites ensemble, tout prend la couleur de la betterave.","Laissez-les refroidir complètement puis pelez-les et taillez-les en dés d'un centimètre, réguliers.","Enrobez les dés de betterave seuls d'une cuillerée d'huile avant de les mêler au reste : l'huile les scelle et empêche la salade de virer au rouge uniforme.","Ajoutez cornichons, choucroute pressée, oignon et haricots, puis l'huile restante, le sel et le poivre.","Laissez reposer 2 heures au frais avant de servir, et remuez au dernier moment seulement. Ne mettez jamais de mayonnaise : ce n'est plus un vinegret."],
     en:["Boil the beetroot, potatoes and carrots whole in their skins, separately: cooked together, everything takes the colour of the beetroot.","Cool them completely then peel and cut them into even one-centimetre dice.","Coat the beetroot dice alone with a spoonful of oil before mixing them with the rest: the oil seals them and stops the salad turning uniformly red.","Add the gherkins, pressed sauerkraut, onion and beans, then the remaining oil, salt and pepper.","Rest 2 hours in the cold before serving, and toss only at the last moment. Never add mayonnaise: it is no longer a vinegret."]} },

{ id:'salade-mimosa', c:'eu', lat:59.930, lon:30.360, base:6, prep:50, cook:20, diff:1, tags:['sea','fresh','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'salad',food:['#e8c46a','#f4f0e6','#e0a8a0','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Salade mimosa',en:'Mimosa salad'},
  p:{fr:'Saint-Pétersbourg, Russie',en:'Saint Petersburg, Russia'},
  d:{fr:"Une salade montée en couches de saumon en conserve, d'œufs et de fromage, couronnée de jaune émietté. Elle se sert le 8 mars, jour des femmes, quand les mimosas arrivaient de Géorgie et d'Abkhazie : le jaune râpé sur le dessus imite la fleur, et c'est de là que vient le nom.",
     en:"A layered salad of tinned salmon, egg and cheese, crowned with crumbled yolk. It is served on 8 March, women's day, when mimosa arrived from Georgia and Abkhazia: the grated yolk on top imitates the flower, and that is where the name comes from."},
  i:[['canned_salmon',250,'g'],['egg',5,'pc'],['cheddar_cheese',100,'g'],['butter',100,'g'],['onion',1,'pc'],['mayonnaise',200,'g'],['potato',300,'g'],['carrot',2,'pc'],['dill',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites durcir les œufs 9 minutes, rafraîchissez-les et séparez soigneusement les blancs des jaunes : la salade tient à cette séparation.","Congelez le beurre une heure : râpé glacé, il forme des filaments qui fondent en bouche, ramolli il ferait une couche grasse.","Écrasez le saumon à la fourchette en retirant peau et arêtes, et faites dégorger l'oignon haché dix minutes à l'eau froide.","Montez dans un cercle : pomme de terre râpée, saumon, oignon, blancs râpés, beurre râpé, fromage, carotte, en fine couche de mayonnaise entre chacune.","Terminez par les jaunes passés au tamis fin, en pluie légère et sans tasser. Laissez prendre 4 heures au froid avant de retirer le cercle."],
     en:["Hard-boil the eggs 9 minutes, refresh them and separate the whites from the yolks carefully: the salad depends on that separation.","Freeze the butter for an hour: grated frozen it forms threads that melt in the mouth, softened it would make a greasy layer.","Mash the salmon with a fork removing skin and bones, and soak the chopped onion ten minutes in cold water.","Build inside a ring: grated potato, salmon, onion, grated white, grated butter, cheese, carrot, with a thin layer of mayonnaise between each.","Finish with the yolks pushed through a fine sieve, rained on lightly and not pressed down. Set 4 hours in the cold before lifting the ring."]} },

{ id:'seledka-pod-shuboy', c:'eu', lat:68.970, lon:33.075, base:6, prep:60, cook:50, diff:2, tags:['sea','fresh','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'salad',food:['#8f2a4a','#f4f0e6','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Hareng sous un manteau de fourrure',en:'Herring under a fur coat'},
  p:{fr:'Mourmansk, Russie',en:'Murmansk, Russia'},
  d:{fr:"Du hareng salé enfoui sous des couches de légumes râpés et de mayonnaise, coiffé de betterave violette. Une légende de 1918 veut que les couleurs disent la révolution — rouge pour les bolcheviks, blanc pour la mayonnaise bourgeoise ; les historiens n'y croient pas, et le plat se sert quand même à chaque Nouvel An.",
     en:"Salted herring buried under layers of grated vegetable and mayonnaise, topped with violet beetroot. A 1918 legend says the colours spell out the revolution — red for the Bolsheviks, white for bourgeois mayonnaise; historians disbelieve it, and the dish is served every New Year regardless."},
  i:[['salted_herring',2,'pc'],['beetroot',3,'pc'],['potato',400,'g'],['carrot',3,'pc'],['onion',1,'pc'],['mayonnaise',300,'g'],['egg',3,'pc'],['white_vinegar',2,'tbsp'],['sunflower_oil',20,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Levez les filets de hareng, retirez toutes les arêtes à la pince et taillez-les en dés d'un centimètre.","Faites dégorger l'oignon haché vingt minutes dans l'eau vinaigrée : cru, il domine toutes les couches suivantes.","Cuisez betteraves, pommes de terre et carottes entières et laissez-les refroidir entièrement — râpées tièdes, elles détrempent la mayonnaise.","Montez dans un plat : hareng, oignon, pomme de terre, carotte, œuf, betterave, en fine couche de mayonnaise entre chacune, sans tasser.","Laissez reposer 12 heures au froid : c'est ce repos qui fait migrer le sel du hareng dans les légumes et qui unifie le plat."],
     en:["Fillet the herring, pull every bone with tweezers and cut it into one-centimetre dice.","Soak the chopped onion for twenty minutes in vinegared water: raw, it dominates every layer above it.","Boil the beetroot, potatoes and carrots whole and cool them completely — grated warm, they soak the mayonnaise.","Build in a dish: herring, onion, potato, carrot, egg, beetroot, with a thin layer of mayonnaise between each, without pressing.","Rest 12 hours in the cold: that rest is what carries the herring's salt into the vegetables and pulls the dish together."]} },

{ id:'khychin-balkar', c:'eu', lat:43.485, lon:43.607, base:6, prep:70, cook:25, diff:2, tags:['cheese','bread','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Khytchin balkar',en:'Balkar khychin'},
  p:{fr:'Naltchik, Kabardino-Balkarie, Russie',en:'Nalchik, Kabardino-Balkaria, Russia'},
  d:{fr:"Une galette très fine fourrée de fromage et de pomme de terre, cuite à sec puis beurrée. Les Balkars, peuple des hautes vallées du Caucase, en empilent une dizaine et les coupent en parts comme un gâteau ; la pâte au kéfir doit être si fine qu'on voit la farce par transparence.",
     en:"A very thin flatbread filled with cheese and potato, cooked dry then buttered. The Balkars, a people of the high Caucasus valleys, stack ten of them and cut them in wedges like a cake; the kefir dough must be so thin the filling shows through."},
  i:[['flour',500,'g'],['kefir',300,'ml'],['potato',300,'g'],['fresh_cheese',300,'g'],['butter',120,'g'],['baking_soda',1,'tsp'],['nettles',200,'g'],['spring_onion',4,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Mêlez le kéfir et le bicarbonate et attendez qu'ils moussent avant d'ajouter la farine et le sel : c'est cette réaction qui remplace la levure.","Pétrissez brièvement, sans forcer, et laissez la pâte reposer 30 minutes sous un bol — trop travaillée, elle se rétracte et ne s'abaisse plus.","Écrasez la pomme de terre chaude avec le fromage frais et l'oignon vert, ou remplacez la pomme de terre par des orties blanchies au printemps.","Enfermez une boule de farce dans une boule de pâte, soudez, puis abaissez au rouleau très doucement jusqu'à 25 cm de diamètre.","Cuisez sur une plaque sèche 3 minutes par face, piquez les cloques, et beurrez généreusement des deux côtés dès la sortie."],
     en:["Mix the kefir and bicarbonate and wait for them to foam before adding the flour and salt: that reaction stands in for yeast.","Knead briefly, without force, and rest the dough 30 minutes under a bowl — overworked, it shrinks back and will not roll.","Mash the hot potato with the fresh cheese and spring onion, or replace the potato with blanched nettles in spring.","Enclose a ball of filling in a ball of dough, seal it, then roll very gently out to 25 cm across.","Cook on a dry griddle 3 minutes a side, prick the blisters, and butter generously on both sides as it comes off."]} },

{ id:'shurpa-daguestan', c:'eu', lat:42.983, lon:47.505, base:6, prep:40, cook:150, diff:2, tags:['lamb','soup','slow'],
  art:{v:'bowl',bg:'#33301f',plate:'#f0e4c8',style:'soup',food:['#e0b45a','#8f5a3a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Chourpa du Daghestan',en:'Dagestani shurpa'},
  p:{fr:'Makhatchkala, Daghestan, Russie',en:'Makhachkala, Dagestan, Russia'},
  d:{fr:"Une soupe d'agneau aux légumes laissés entiers, cuite au kazan sur le feu. Les légumes ne sont pas coupés : ils cuisent en gardant leur forme et se servent à part de la viande, et le bouillon se boit seul dans un bol, avant le reste.",
     en:"A lamb soup with vegetables left whole, cooked in a kazan over the fire. The vegetables are not cut: they cook keeping their shape and are served apart from the meat, and the broth is drunk on its own from a bowl, before the rest."},
  i:[['lamb_shoulder',1,'kg'],['lamb_bones',500,'g'],['potato',4,'pc'],['ripe_tomato',3,'pc'],['onion',2,'pc'],['carrot',3,'pc'],['chickpeas',200,'g'],['cumin',1,'tbsp'],['cilantro',1,'bunch'],['red_pepper',1,'pc'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pois chiches une nuit, puis mettez la viande et les os à l'eau froide et montez lentement.","Écumez sans relâche pendant le premier quart d'heure : au Daghestan on juge une chourpa à la transparence de son bouillon.","Ajoutez les pois chiches et laissez frémir 1 h 30 sans jamais bouillir, à découvert, en complétant l'eau évaporée.","Ajoutez ensuite les légumes entiers — oignons, carottes, pommes de terre — et laissez 40 minutes de plus.","Servez en trois temps : le bouillon d'abord, dans un bol, puis les légumes, puis la viande sur un plat, avec de la coriandre et du cumin moulu."],
     en:["Soak the chickpeas overnight, then start the meat and bones in cold water and bring them up slowly.","Skim without pause for the first fifteen minutes: in Dagestan a shurpa is judged by the clarity of its broth.","Add the chickpeas and simmer 1½ hours without ever boiling, uncovered, topping up the evaporated water.","Then add the whole vegetables — onions, carrots, potatoes — and give them 40 minutes more.","Serve in three acts: the broth first, in a bowl, then the vegetables, then the meat on a platter, with coriander and ground cumin."]} },

{ id:'veau-orloff', c:'eu', lat:55.762, lon:37.607, base:6, prep:60, cook:70, diff:3, tags:['beef','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#c9924a','#8f6a4a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Veau Orloff',en:'Veal Orloff'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Une longe de veau rôtie, tranchée puis reconstituée avec une duxelles et un soubise entre chaque tranche, nappée de Mornay et gratinée. Créé à Paris par le chef français du prince Orloff, ambassadeur du tsar : c'est un plat russe qui n'a jamais été cuisiné en Russie avant d'y revenir.",
     en:"A roasted veal loin, sliced then reassembled with duxelles and soubise between each slice, coated in Mornay and gratinated. Created in Paris by the French chef of Prince Orlov, the tsar's ambassador: a Russian dish never cooked in Russia before it came back there."},
  i:[['veal',1,'kg'],['button_mushrooms',300,'g'],['onion',400,'g'],['long_grain_rice',60,'g'],['gruyere_cheese',200,'g'],['whole_milk',500,'ml'],['flour',50,'g'],['butter',120,'g'],['heavy_cream',100,'ml'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rôtissez la longe 40 minutes à 180 °C jusqu'à 58 °C à cœur, et laissez-la refroidir : on ne tranche jamais un veau chaud, il s'effrite.","Faites le soubise en cuisant l'oignon émincé et le riz dans le lait 30 minutes, puis mixez et faites dessécher jusqu'à obtenir une purée épaisse.","Faites la duxelles en desséchant les champignons hachés 20 minutes à la poêle, jusqu'à ce qu'ils ne rendent plus rien.","Tranchez le veau à 1 cm, tartinez chaque tranche de soubise et de duxelles, et remontez la longe en la ficelant légèrement.","Nappez d'une Mornay au gruyère, parsemez de fromage et gratinez 25 minutes à 200 °C. Retirez la ficelle avant de servir."],
     en:["Roast the loin 40 minutes at 180°C to 58°C at the centre, and let it cool: veal is never sliced hot, it crumbles.","Make the soubise by cooking the sliced onion and rice in the milk for 30 minutes, then blend and dry it out to a thick purée.","Make the duxelles by drying the chopped mushrooms in a pan for 20 minutes, until they release nothing more.","Slice the veal 1 cm thick, spread each slice with soubise and duxelles, and rebuild the loin, tying it lightly.","Coat with a gruyère Mornay, scatter cheese and gratinate 25 minutes at 200°C. Remove the string before serving."]} },

{ id:'kournik', c:'eu', lat:45.200, lon:38.900, base:10, prep:180, cook:70, diff:3, tags:['poultry','bake','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kournik',en:'Kurnik'},
  p:{fr:'Kouban, Russie',en:'Kuban, Russia'},
  d:{fr:"Une tourte haute en dôme à sept étages — poulet, riz, champignons, œufs — séparés par des crêpes fines. C'est la tourte de mariage cosaque : on la coupait devant les mariés, et le nombre de couches disait le nombre d'enfants qu'on leur souhaitait.",
     en:"A tall domed pie of seven layers — chicken, rice, mushrooms, egg — separated by thin pancakes. It is the Cossack wedding pie: it was cut before the couple, and the number of layers said how many children were wished on them."},
  i:[['chicken',600,'g'],['long_grain_rice',200,'g'],['button_mushrooms',250,'g'],['egg',6,'pc'],['shortcrust_pastry',400,'g'],['puff_pastry',300,'g'],['flour',100,'g'],['whole_milk',250,'ml'],['butter',120,'g'],['onion',2,'pc'],['dill',1,'bunch'],['chicken_broth',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez le poulet 45 minutes, désossez-le à chaud et effilochez la chair ; gardez le bouillon pour cuire le riz.","Faites quatre crêpes fines et laissez-les refroidir à plat : elles séparent les couches et absorbent l'humidité de chacune.","Préparez les garnitures séparément — riz au bouillon et aneth, champignons desséchés à l'oignon, œufs durs hachés, poulet lié d'un peu de bouillon — et laissez tout refroidir.","Foncez de pâte brisée, empilez en dôme : poulet, crêpe, riz, crêpe, champignons, crêpe, œufs, en resserrant vers le haut.","Couvrez d'une abaisse de feuilletée, soudez, dorez, percez une cheminée et cuisez 20 minutes à 200 °C puis 50 minutes à 170 °C."],
     en:["Poach the chicken 45 minutes, bone it hot and shred the meat; keep the broth to cook the rice.","Make four thin pancakes and cool them flat: they divide the layers and absorb the moisture of each.","Prepare the fillings separately — rice in broth with dill, mushrooms dried out with onion, chopped hard-boiled egg, chicken bound with a little broth — and cool everything.","Line with shortcrust and stack into a dome: chicken, pancake, rice, pancake, mushrooms, pancake, egg, narrowing toward the top.","Cover with puff pastry, seal, glaze, cut a chimney and bake 20 minutes at 200°C then 50 minutes at 170°C."]} },

{ id:'kalatch-de-mourom', c:'eu', lat:55.573, lon:42.052, base:8, prep:1440, cook:30, diff:3, tags:['bread','bake','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kalatch de Mourom',en:'Murom kalach'},
  p:{fr:'Mourom, Russie',en:'Murom, Russia'},
  d:{fr:"Un pain de froment en forme de cadenas, muni d'une anse par laquelle on le tient sans le salir. L'anse ne se mangeait pas : on la donnait aux pauvres ou aux chiens, et c'est de là que vient l'expression russe être arrivé jusqu'à l'anse, avoir touché le fond.",
     en:"A wheat bread shaped like a padlock, with a handle to hold it by without soiling it. The handle was not eaten: it was given to the poor or to dogs, and from that comes the Russian phrase to have reached the handle, to have hit rock bottom."},
  i:[['flour',600,'g'],['water',350,'ml'],['sourdough_starter',150,'g'],['sugar',1,'tbsp'],['sunflower_oil',20,'ml'],['salt',null,'']],
  s:{fr:["Rafraîchissez le levain deux fois dans la journée : le kalatch se fait au levain seul, et un levain faible donne un pain plat.","Pétrissez la pâte très ferme, puis travaillez-la longuement sur la table en la frappant et en la repliant, une bonne demi-heure.","Ce battage prolongé chasse les grosses bulles et donne la mie serrée et satinée qui distingue un kalatch d'un pain ordinaire.","Laissez lever une nuit au froid, puis façonnez un anneau épais dont vous étirez une extrémité en anse fine.","Cuisez 30 minutes à 240 °C avec de la vapeur les dix premières minutes. Le ventre doit être doré et l'anse presque blanche."],
     en:["Refresh the starter twice during the day: kalach is made on leaven alone, and a weak starter gives a flat bread.","Knead a very firm dough, then work it at length on the table, slapping and folding it, for a good half hour.","That prolonged beating drives out the large bubbles and gives the tight, satiny crumb that separates a kalach from ordinary bread.","Prove overnight in the cold, then shape a thick ring, drawing one end out into a slim handle.","Bake 30 minutes at 240°C with steam for the first ten. The belly should be golden and the handle almost white."]} },

{ id:'kharcho', c:'eu', lat:43.599, lon:39.730, base:6, prep:40, cook:120, diff:2, tags:['beef','soup','spicy'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#8f2a2a','#c9532c','#e8dcb8','#4f6f3a'],garnish:'#7fae6a'},
  n:{fr:'Kharcho',en:'Kharcho'},
  p:{fr:'Sotchi, Russie',en:'Sochi, Russia'},
  d:{fr:"Une soupe géorgienne de bœuf au riz, aux noix et à la prune aigre tkemali, très épicée. L'acidité ne vient ni du citron ni du vinaigre mais de la prune verte fermentée : c'est elle qui fait le kharcho, et sans elle on obtient une simple soupe de bœuf.",
     en:"A Georgian beef soup with rice, walnuts and sour tkemali plum, heavily spiced. The acidity comes from neither lemon nor vinegar but from fermented green plum: it is what makes a kharcho, and without it you have an ordinary beef soup."},
  i:[['beef_chuck',600,'g'],['long_grain_rice',100,'g'],['walnuts',100,'g'],['tkemali_sauce',100,'ml'],['onion',3,'pc'],['garlic',6,'clove'],['cilantro',2,'bunch'],['khmeli_suneli',1,'tbsp'],['red_chili',2,'pc'],['bay_leaf',2,'pc'],['tomato_paste',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Mettez le bœuf à l'eau froide et montez lentement en écumant, puis laissez frémir 1 h 30 avec le laurier.","Pilez les noix au mortier jusqu'à ce qu'elles rendent leur huile : c'est cette huile, et non les éclats, qui lie la soupe.","Faites fondre l'oignon très finement haché 20 minutes, ajoutez le concentré et laissez-le brunir légèrement.","Réunissez le tout avec le riz et laissez cuire 20 minutes, puis ajoutez le tkemali et le khmeli-suneli hors du feu.","Le mélange d'épices ne doit jamais bouillir : cuit, il perd son parfum de fenugrec et d'aneth. Ajoutez l'ail pilé et la coriandre au dernier moment."],
     en:["Start the beef in cold water and bring it up slowly, skimming, then simmer 1½ hours with the bay.","Pound the walnuts in a mortar until they release their oil: it is that oil, not the fragments, that binds the soup.","Melt the very finely chopped onion for 20 minutes, add the tomato purée and let it darken slightly.","Bring everything together with the rice and cook 20 minutes, then add the tkemali and khmeli-suneli off the heat.","The spice mix must never boil: cooked, it loses its fenugreek and dill scent. Add the pounded garlic and coriander at the last moment."]} },

{ id:'pyshki-petersbourg', c:'eu', lat:59.937, lon:30.328, base:8, prep:100, cook:20, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f4f0e6','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pychki de Saint-Pétersbourg',en:'Petersburg pyshki'},
  p:{fr:'Saint-Pétersbourg, Russie',en:'Saint Petersburg, Russia'},
  d:{fr:"Des anneaux de pâte levée frits et noyés de sucre glace, institution de la rue Bolchaïa Koniouchennaïa depuis 1958. On ne les appelle jamais des donuts à Saint-Pétersbourg : la pychka n'a pas de garniture, se mange debout et s'accompagne d'un café au lait servi dans un verre.",
     en:"Rings of yeasted dough fried and buried in icing sugar, an institution on Bolshaya Konyushennaya street since 1958. In Petersburg they are never called doughnuts: a pyshka has no filling, is eaten standing and comes with milky coffee served in a glass."},
  i:[['flour',500,'g'],['whole_milk',300,'ml'],['fresh_yeast',20,'g'],['egg',2,'pc'],['sugar',50,'g'],['butter',40,'g'],['sunflower_oil',1.5,'l'],['powdered_sugar',150,'g'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec une cuillerée de sucre et attendez qu'elle mousse franchement.","Pétrissez avec la farine, les œufs, le sucre, le sel et le beurre fondu 12 minutes : la pâte doit rester molle et légèrement collante.","Laissez lever 1 heure, puis abaissez à 1,5 cm et découpez des anneaux à l'emporte-pièce, sans repétrir les chutes plus d'une fois.","Laissez-les pousser 25 minutes sur un linge fariné, à découvert : une légère croûte se forme et empêche la pychka de boire l'huile.","Frites 90 secondes par face à 180 °C, égouttez et roulez-les dans le sucre glace pendant qu'elles sont brûlantes."],
     en:["Dissolve the yeast in warm milk with a spoonful of sugar and wait until it foams properly.","Knead with the flour, eggs, sugar, salt and melted butter for 12 minutes: the dough must stay soft and slightly tacky.","Prove for an hour, then roll to 1.5 cm and cut rings with a cutter, re-rolling the trimmings once only.","Prove them 25 minutes on a floured cloth, uncovered: a light skin forms and keeps the pyshka from drinking oil.","Fry 90 seconds a side at 180°C, drain and roll them in icing sugar while they are still scalding."]} },

{ id:'plombir-sovietique', c:'eu', lat:55.758, lon:37.615, base:8, prep:240, cook:15, diff:2, tags:['sweet','fresh','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f2dfa8','#f0e8d0','#e8dcb8'],garnish:'#c9754a'},
  n:{fr:'Plombir soviétique',en:'Soviet plombir'},
  p:{fr:'Moscou, Russie',en:'Moscow, Russia'},
  d:{fr:"Une glace à la crème très grasse, sans stabilisant ni arôme, telle que la norme GOST la définissait. Mikoïan, commissaire à l'alimentation, rapporta les machines des États-Unis en 1936 et imposa quinze pour cent de matière grasse ; on la vendait dehors, même à moins vingt.",
     en:"An ice cream of very rich cream, with no stabiliser and no flavouring, as the GOST standard defined it. Mikoyan, commissar for food, brought the machines back from the United States in 1936 and imposed fifteen per cent fat; it was sold outdoors, even at minus twenty."},
  i:[['heavy_cream',500,'ml'],['whole_milk',200,'ml'],['sugar',150,'g'],['egg_yolk',4,'pc'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Faites infuser la gousse de vanille fendue dans le lait chaud une demi-heure, hors du feu, puis retirez-la en raclant les graines.","Blanchissez les jaunes avec le sucre, versez le lait tiède dessus et cuisez à la nappe jusqu'à 83 °C, sans jamais dépasser.","À 85 °C les jaunes coagulent et la crème grène : c'est la seule vraie difficulté, et un thermomètre vaut mieux qu'un coup d'œil.","Filtrez, refroidissez rapidement dans un bain d'eau glacée, ajoutez la crème froide et laissez maturer 4 heures au réfrigérateur.","Turbinez, puis laissez durcir 3 heures au congélateur. Sans stabilisant, elle cristallise en deux jours : elle se mange dans la journée."],
     en:["Infuse the split vanilla pod in the hot milk for half an hour off the heat, then lift it out, scraping the seeds in.","Whiten the yolks with the sugar, pour the warm milk over and cook to the nappe at 83°C, never above.","At 85°C the yolks coagulate and the custard grains: that is the only real difficulty, and a thermometer beats an eye.","Strain, cool fast in an iced water bath, add the cold cream and mature 4 hours in the fridge.","Churn, then harden 3 hours in the freezer. With no stabiliser it crystallises within two days: it is eaten the same day."]} },

{ id:'sbiten', c:'eu', lat:58.522, lon:31.270, base:6, prep:15, cook:30, diff:1, tags:['drink','comfort','fast'],
  art:{v:'glass',bg:'#2b2419',plate:'#f4f0e6',style:'drink',food:['#8f5a3a','#c9924a','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Sbiten',en:'Sbiten'},
  p:{fr:'Veliki Novgorod, Russie',en:'Veliky Novgorod, Russia'},
  d:{fr:"Une boisson chaude au miel et aux épices, bue dans les rues russes avant que le thé n'arrive de Chine en 1638. Les marchands ambulants la portaient dans des samovars de cuivre sur le dos et criaient sbiten ! ; le nom vient de sbivat, battre ensemble.",
     en:"A hot honey and spice drink, sold in Russian streets before tea arrived from China in 1638. Street sellers carried it in copper samovars on their backs crying sbiten!; the name comes from sbivat, to beat together."},
  i:[['honey',200,'g'],['sugar',80,'g'],['water',1.2,'l'],['cinnamon',2,'stick'],['cloves',8,'pc'],['ginger',30,'g'],['mint',1,'bunch'],['star_anise',2,'pc'],['black_peppercorns',5,'pc'],['lemon',1,'pc']],
  s:{fr:["Portez l'eau et le sucre à ébullition avec le gingembre frais tranché, la cannelle, les clous, l'anis et quelques grains de poivre.","Laissez infuser 20 minutes à couvert, à feu très doux, sans jamais bouillir franchement.","Retirez du feu et laissez descendre à 60 °C avant d'incorporer le miel : au-delà, il perd ses arômes et ne laisse que son sucre.","Ajoutez la menthe et le zeste de citron et laissez infuser dix minutes de plus, hors du feu et à couvert.","Filtrez et servez brûlant dans des verres épais préalablement ébouillantés. On y ajoutait autrefois du vin, ce qui reste facultatif."],
     en:["Bring the water and sugar to the boil with sliced fresh ginger, cinnamon, cloves, star anise and a few peppercorns.","Infuse 20 minutes covered over very low heat, never at a rolling boil.","Take it off and let it fall to 60°C before stirring in the honey: above that it loses its aromas and leaves only its sugar.","Add the mint and lemon zest and infuse ten minutes more, off the heat and covered.","Strain and serve scalding in thick glasses scalded beforehand. Wine was once added, which remains optional."]} },

{ id:'kvass-blanc', c:'eu', lat:56.427, lon:40.442, base:10, prep:2880, cook:20, diff:2, tags:['drink','fresh','slow'],
  art:{v:'glass',bg:'#2b2419',plate:'#f4f0e6',style:'drink',food:['#8f6a4a','#c9a878','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kvass de pain',en:'Bread kvass'},
  p:{fr:'Souzdal, Russie',en:'Suzdal, Russia'},
  d:{fr:"Une boisson fermentée de pain de seigle grillé, à peine alcoolisée, bue glacée l'été. Elle est mentionnée dans la chronique de 996, quand Vladimir baptise la Rus' et fait distribuer du kvass au peuple ; on la vendait à la citerne dans la rue jusque dans les années 1990.",
     en:"A fermented drink of toasted rye bread, barely alcoholic, drunk iced in summer. It appears in the chronicle of 996, when Vladimir baptised the Rus' and had kvass distributed to the people; it was sold from street tankers into the 1990s."},
  i:[['rye_bread',500,'g'],['water',5,'l'],['sugar',150,'g'],['fresh_yeast',10,'g'],['raisins',30,'g'],['mint',1,'bunch']],
  s:{fr:["Coupez le pain de seigle en tranches et faites-les brunir au four 20 minutes à 180 °C, jusqu'aux bords presque noirs.","C'est ce grillage poussé qui donne la couleur et le goût : un pain simplement séché produit un kvass pâle et fade.","Versez l'eau bouillante sur le pain et laissez infuser 8 heures, puis filtrez à travers un linge sans presser.","Ajoutez le sucre et la levure délayée, couvrez d'un linge — jamais d'un couvercle hermétique — et laissez fermenter 24 heures à température ambiante.","Mettez en bouteilles avec trois raisins secs par bouteille, fermez et laissez 24 heures de plus au froid. Ouvrez au-dessus de l'évier : la pression est réelle."],
     en:["Cut the rye bread into slices and brown them in the oven 20 minutes at 180°C, until the edges are nearly black.","That deep toasting gives the colour and the flavour: merely dried bread makes a pale, bland kvass.","Pour boiling water over the bread and infuse 8 hours, then strain through a cloth without pressing.","Add the sugar and the slaked yeast, cover with a cloth — never an airtight lid — and ferment 24 hours at room temperature.","Bottle with three raisins per bottle, close and leave 24 hours more in the cold. Open over the sink: the pressure is real."]} },

{ id:'tchakhokhbili', c:'eu', lat:45.043, lon:38.967, base:4, prep:30, cook:60, diff:2, tags:['poultry','stew','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9532c','#e0913a','#4f6f3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Tchakhokhbili',en:'Chakhokhbili'},
  p:{fr:'Krasnodar, Russie',en:'Krasnodar, Russia'},
  d:{fr:"Un ragoût de volaille aux tomates et aux herbes, cuit sans une goutte d'eau. Le nom vient de khokhobi, le faisan en géorgien, remplacé par du poulet dès l'époque soviétique ; la viande se saisit à sec dans la cocotte avant tout, et c'est son propre jus qui fait la sauce.",
     en:"A poultry stew with tomatoes and herbs, cooked without a drop of water. The name comes from khokhobi, Georgian for pheasant, replaced by chicken in Soviet times; the meat is seared dry in the pot first, and its own juices make the sauce."},
  i:[['chicken',1.5,'kg'],['ripe_tomato',1,'kg'],['onion',500,'g'],['garlic',6,'clove'],['cilantro',2,'bunch'],['basil',1,'bunch'],['khmeli_suneli',1,'tbsp'],['red_chili',2,'pc'],['white_wine',100,'ml'],['butter',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le poulet en morceaux et faites-les colorer dans la cocotte sèche, sans matière grasse : la peau rend assez de graisse pour la suite.","Retirez-les et faites fondre l'oignon en lamelles épaisses dans cette graisse, 25 minutes, jusqu'à ce qu'il soit blond et fondant.","Pelez les tomates après les avoir ébouillantées trente secondes, et concassez-les grossièrement à la main.","Remettez le poulet avec la tomate, couvrez et laissez mijoter 40 minutes sans ajouter d'eau : la tomate et l'oignon en donnent assez.","Ajoutez l'ail pilé, le khmeli-suneli et les herbes hachées seulement dans les cinq dernières minutes, hors ébullition."],
     en:["Joint the chicken and colour the pieces in a dry pot, with no fat: the skin releases enough for what follows.","Lift them out and melt thickly sliced onion in that fat for 25 minutes, until pale and yielding.","Peel the tomatoes after thirty seconds in boiling water, and crush them roughly by hand.","Return the chicken with the tomato, cover and simmer 40 minutes without adding water: the tomato and onion give enough.","Add the pounded garlic, khmeli-suneli and chopped herbs only in the last five minutes, off the boil."]} },

{ id:'balyk-de-saumon', c:'as', lat:43.115, lon:131.886, base:8, prep:2880, cook:0, diff:3, tags:['sea','slow','fresh'],
  art:{v:'board',bg:'#26384a',plate:'#f4ead4',style:'fish',food:['#e0a8a0','#f0e8d0','#c9754a','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Balyk de saumon',en:'Salmon balyk'},
  p:{fr:'Vladivostok, Russie',en:'Vladivostok, Russia'},
  d:{fr:"Le dos du saumon rouge salé puis séché à l'air froid, tranché aussi fin que possible. Le balyk n'emploie que la partie dorsale, la plus grasse et la plus dense ; le ventre, trop fin, est mis à part et fumé séparément sous le nom de teïcha.",
     en:"The back of a sockeye salmon salted then air-dried in the cold, sliced as thin as possible. Balyk uses only the dorsal part, the fattest and densest; the belly, too thin, is set aside and smoked separately under the name teysha."},
  i:[['salmon',1,'kg'],['coarse_salt',150,'g'],['sugar',50,'g'],['black_peppercorns',1,'tbsp'],['bay_leaf',4,'pc'],['rye_bread',400,'g'],['butter',80,'g'],['lemon',1,'pc']],
  s:{fr:["Levez le dos du saumon en un seul morceau, sans le ventre, et retirez toutes les arêtes à la pince.","Mêlez le sel, le sucre, le poivre concassé et le laurier émietté, et enfouissez le poisson dedans, chair contre chair s'il y a deux morceaux.","Laissez saler 48 heures au froid en retournant matin et soir, et videz la saumure qui se forme à chaque fois.","Rincez, épongez, puis suspendez à l'air froid et ventilé — entre 2 et 6 °C — pendant cinq à sept jours, enveloppé d'une gaze contre les mouches.","Il est prêt quand la chair a perdu un tiers de son poids et qu'elle est translucide et ferme. Tranchez au couteau long, presque à plat, et servez sur du pain de seigle beurré."],
     en:["Take the back of the salmon off in one piece, without the belly, and pull every bone with tweezers.","Mix the salt, sugar, cracked pepper and crumbled bay, and bury the fish in it, flesh to flesh if there are two pieces.","Cure 48 hours in the cold, turning morning and evening, and pouring off the brine each time.","Rinse, blot, then hang in cold moving air — between 2 and 6°C — for five to seven days, wrapped in muslin against flies.","It is ready when it has lost a third of its weight and the flesh is translucent and firm. Slice with a long knife, almost flat, and serve on buttered rye bread."]} },

{ id:'pelmeni-au-renne', c:'as', lat:62.028, lon:129.732, base:6, prep:120, cook:10, diff:2, tags:['slow','comfort','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pelmenis au renne',en:'Reindeer pelmeni'},
  p:{fr:'Iakoutsk, Iakoutie, Russie',en:'Yakutsk, Yakutia, Russia'},
  d:{fr:"Des raviolis de renne façonnés par centaines et congelés dehors, dans le froid de Iakoutie. La viande de renne est si maigre qu'elle resterait sèche : on y ajoute de la moelle ou du gras de porc, et les pelmenis se conservent tout l'hiver dans un sac accroché sous l'auvent.",
     en:"Reindeer dumplings shaped by the hundred and frozen outdoors, in the Yakutian cold. Reindeer meat is so lean it would stay dry: marrow or pork fat is added, and the pelmeni keep all winter in a sack hung under the eaves."},
  i:[['venison',400,'g'],['pork_fat',120,'g'],['flour',400,'g'],['egg',1,'pc'],['water',150,'ml'],['onion',2,'pc'],['beef_broth',1,'l'],['smetana',150,'g'],['black_peppercorns',1,'tbsp'],['dill',1,'bunch'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, l'œuf, l'eau glacée et le sel 15 minutes en une pâte très ferme, et laissez-la reposer 1 heure enveloppée.","Hachez la viande et le gras au couteau, pas au robot, et ajoutez l'oignon râpé avec son jus et deux cuillerées d'eau glacée.","Cette eau est le jus du pelmeni : sans elle, la viande de renne cuit sec et le ravioli n'a aucun intérêt.","Abaissez à 1 mm, découpez des ronds de 6 cm, garnissez, pliez en demi-lune puis joignez les deux pointes en anneau.","Congelez-les à plat une heure avant de les cuire : ils tiennent mieux. Pochez 6 minutes dans un bouillon frémissant, jusqu'à ce qu'ils remontent, et servez à la smetana."],
     en:["Knead the flour, egg, iced water and salt for 15 minutes into a very firm dough, and rest it an hour wrapped.","Chop the meat and fat by knife, not in a processor, and add grated onion with its juice and two spoonfuls of iced water.","That water is the pelmen's juice: without it the reindeer cooks dry and the dumpling has no point.","Roll to 1 mm, cut 6 cm rounds, fill, fold into half-moons then join the two points into a ring.","Freeze them flat for an hour before cooking: they hold better. Poach 6 minutes in simmering broth until they rise, and serve with smetana."]} },

{ id:'omoul-fume-du-baikal', c:'as', lat:51.860, lon:104.868, base:6, prep:1440, cook:180, diff:3, tags:['sea','slow','fresh'],
  art:{v:'board',bg:'#26384a',plate:'#f4ead4',style:'fish',food:['#c9924a','#8f6a4a','#f0e8d0','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Omoul fumé du Baïkal',en:'Smoked Baikal omul'},
  p:{fr:'Listvianka, Baïkal, Russie',en:'Listvyanka, Lake Baikal, Russia'},
  d:{fr:"Un corégone endémique du Baïkal, salé puis fumé à chaud au bois d'aulne sur la rive. L'omoul ne vit nulle part ailleurs et sa pêche est réglementée depuis 2017 ; sa chair est si grasse qu'elle n'a besoin d'aucune matière grasse ajoutée pour rester moelleuse.",
     en:"A whitefish found only in Lake Baikal, salted then hot-smoked over alder on the shore. Omul lives nowhere else and its fishing has been restricted since 2017; its flesh is so fatty that it needs no added fat to stay moist."},
  i:[['whitefish',4,'pc'],['coarse_salt',200,'g'],['black_peppercorns',1,'tbsp'],['alder_chips',300,'g'],['bay_leaf',3,'pc'],['rye_bread',400,'g'],['spring_onion',4,'pc']],
  s:{fr:["Videz les poissons sans les écailler et retirez les ouïes, qui donneraient de l'amertume au fumage.","Salez-les à sec en frottant l'intérieur et l'extérieur, et laissez-les 12 heures au froid sous un léger poids.","Rincez, puis laissez-les sécher 3 heures suspendus à l'air : la peau doit être sèche au toucher, faute de quoi la fumée glisse dessus sans accrocher.","Faites un lit de copeaux d'aulne humidifiés dans le fumoir et maintenez 80 °C : c'est un fumage à chaud, le poisson cuit en même temps qu'il prend la fumée.","Comptez 2 h 30 jusqu'à ce que la peau soit brun doré et que la chair se détache de l'arête. Se mange tiède, à la main, avec du pain noir."],
     en:["Gut the fish without scaling them and remove the gills, which would bring bitterness to the smoking.","Dry-salt them, rubbing inside and out, and leave them 12 hours in the cold under a light weight.","Rinse, then hang them to dry for 3 hours in the air: the skin must be dry to the touch, otherwise the smoke slides off without taking.","Lay dampened alder chips in the smoker and hold 80°C: this is hot smoking, the fish cooks as it takes the smoke.","Allow 2½ hours until the skin is golden brown and the flesh lifts from the bone. Eaten warm, with the fingers, and black bread."]} },

{ id:'chou-a-la-sakhaline', c:'as', lat:46.959, lon:142.738, base:8, prep:120, cook:0, diff:2, tags:['veg','spicy','slow'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#c9402c','#e0913a','#f2dfa8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chou fermenté de Sakhaline',en:'Sakhalin fermented cabbage'},
  p:{fr:'Ioujno-Sakhalinsk, Sakhaline, Russie',en:'Yuzhno-Sakhalinsk, Sakhalin, Russia'},
  d:{fr:"Du chou chinois fermenté au piment, à l'ail et au varech, cousin russe du kimchi. L'île fut japonaise jusqu'en 1945 et compte une communauté coréenne déportée : ce chou est né de cette rencontre, et le kombu qu'on y ajoute est l'apport local.",
     en:"Chinese cabbage fermented with chilli, garlic and kelp, a Russian cousin of kimchi. The island was Japanese until 1945 and holds a deported Korean community: this cabbage was born of that meeting, and the kombu in it is the local addition."},
  i:[['napa_cabbage',1.5,'kg'],['coarse_salt',100,'g'],['daikon',300,'g'],['kombu',20,'g'],['garlic',10,'clove'],['ginger',40,'g'],['gochugaru',60,'g'],['fish_sauce',60,'ml'],['spring_onion',6,'pc'],['sugar',1,'tbsp']],
  s:{fr:["Fendez les choux en quatre dans la longueur, salez entre chaque feuille et laissez dégorger 4 heures en les retournant deux fois.","Rincez trois fois à l'eau claire et pressez : il doit rester juste assez de sel pour que la feuille plie sans casser.","Faites tremper le kombu 30 minutes, puis mixez-le avec l'ail, le gingembre, le sucre et la sauce de poisson en une pâte.","Mêlez cette pâte au piment coréen jusqu'à obtenir une purée rouge vif, et enduisez-en chaque feuille, une par une, à la main gantée.","Tassez dans un bocal en chassant l'air, laissez fermenter 2 jours à température ambiante puis passez au froid. Il se mange à partir d'une semaine et se garde tout l'hiver."],
     en:["Quarter the cabbages lengthwise, salt between every leaf and let them drain 4 hours, turning twice.","Rinse three times in clear water and press: just enough salt must remain for the leaf to fold without snapping.","Soak the kombu 30 minutes, then blend it with the garlic, ginger, sugar and fish sauce into a paste.","Mix that paste with the Korean chilli to a bright red purée, and coat every leaf, one by one, with a gloved hand.","Pack into a jar expelling the air, ferment 2 days at room temperature then move to the cold. It is eaten from a week on and keeps all winter."]} },

{ id:'pelmeni-de-sakhaline', c:'as', lat:46.951, lon:142.752, base:6, prep:110, cook:10, diff:3, tags:['sea','comfort','festive'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e07a6a','#e8dcb8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Pelmenis de Sakhaline aux fruits de mer',en:'Sakhalin seafood pelmeni'},
  p:{fr:'Ioujno-Sakhalinsk, Sakhaline, Russie',en:'Yuzhno-Sakhalinsk, Sakhalin, Russia'},
  d:{fr:"Des raviolis au crabe, aux pétoncles et aux crevettes, nés dans les cantines des plateformes pétrolières de l'île. La farce ne se hache pas : les chairs restent en morceaux reconnaissables, et le pelmeni se poche moins longtemps que son cousin de viande.",
     en:"Dumplings of crab, scallop and prawn, born in the canteens of the island's oil platforms. The filling is not minced: the flesh stays in recognisable pieces, and the dumpling poaches for less time than its meat cousin."},
  i:[['crab_meat',300,'g'],['scallops',200,'g'],['shrimp',150,'g'],['flour',400,'g'],['egg',1,'pc'],['water',150,'ml'],['spring_onion',5,'pc'],['ginger',20,'g'],['butter',80,'g'],['soy_sauce',40,'ml'],['sesame_oil',10,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la pâte à pelmeni comme d'habitude et laissez-la reposer une heure : elle doit être ferme et fine, la mer ne pardonne pas une pâte épaisse.","Taillez le pétoncle et la crevette au couteau en morceaux d'un demi-centimètre, et effilochez le crabe à la main.","Ne mixez rien : une farce de mer réduite en pâte perd sa texture et prend un goût de conserve.","Ajoutez l'oignon vert, le gingembre râpé, une pincée de sel et rien de plus — surtout pas d'œuf, qui masquerait tout.","Façonnez et pochez 4 minutes seulement dans une eau frémissante salée. Servez avec un beurre fondu au soja et quelques gouttes d'huile de sésame."],
     en:["Knead the pelmeni dough as usual and rest it an hour: it must be firm and thin, the sea does not forgive thick pastry.","Cut the scallop and prawn by knife into half-centimetre pieces, and shred the crab by hand.","Blend nothing: a seafood filling reduced to a paste loses its texture and takes on a tinned taste.","Add the spring onion, grated ginger, a pinch of salt and nothing more — certainly no egg, which would mask everything.","Shape them and poach 4 minutes only in simmering salted water. Serve with melted butter and soy, and a few drops of sesame oil."]} },

{ id:'manty-siberiens', c:'as', lat:55.008, lon:82.935, base:6, prep:120, cook:45, diff:2, tags:['beef','comfort','slow'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e0913a','#e8dcb8','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Manty sibériens',en:'Siberian manty'},
  p:{fr:'Novossibirsk, Russie',en:'Novosibirsk, Russia'},
  d:{fr:"De gros raviolis vapeur de cent grammes, farcis de bœuf, d'oignon et de courge. La courge n'est pas un remplissage d'économie : elle fond et rend son eau sucrée pendant la cuisson, ce qui nourrit une viande maigre que rien d'autre n'humidifierait.",
     en:"Large steamed dumplings of a hundred grams, filled with beef, onion and pumpkin. The pumpkin is no cheap filler: it melts and releases its sweet water as it cooks, feeding a lean meat that nothing else would moisten."},
  i:[['flour',500,'g'],['water',220,'ml'],['egg',1,'pc'],['ground_beef',600,'g'],['onion',300,'g'],['pumpkin',200,'g'],['pork_fat',80,'g'],['cumin',1,'tsp'],['black_peppercorns',1,'tbsp'],['smetana',150,'g'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme à l'eau tiède et laissez-la reposer 1 heure : les manty se plient beaucoup et une pâte cassante se déchire.","Taillez la viande, le gras et la courge au couteau en dés de 5 mm, et hachez l'oignon très finement.","La proportion compte : autant d'oignon que de la moitié du poids de viande, faute de quoi la farce reste sèche.","Découpez des carrés de 12 cm, garnissez et joignez les quatre coins au centre, puis soudez les quatre fentes deux à deux.","Huilez les plateaux du cuit-vapeur — les manty collent et se déchirent sinon — et cuisez 40 minutes. Servez au beurre fondu et à la smetana."],
     en:["Knead a firm dough with warm water and rest it an hour: manty are folded a great deal and a brittle dough tears.","Cut the meat, fat and pumpkin by knife into 5 mm dice, and chop the onion very finely.","The proportion matters: as much onion as half the weight of meat, otherwise the filling stays dry.","Cut 12 cm squares, fill them and bring the four corners to the centre, then seal the four openings in pairs.","Oil the steamer trays — manty stick and tear otherwise — and steam 40 minutes. Serve with melted butter and smetana."]} },

{ id:'langue-de-renne-dolgane', c:'as', lat:69.349, lon:88.201, base:6, prep:40, cook:150, diff:2, tags:['slow','festive','fresh'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#e0a8a0','#f4f0e6','#c9a878','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Langue de renne à la dolgane',en:'Dolgan reindeer tongue'},
  p:{fr:'Norilsk, Taïmyr, Russie',en:'Norilsk, Taymyr, Russia'},
  d:{fr:"Des langues de renne pochées aux baies de genièvre, pressées et servies froides en fines tranches. Les Dolganes, éleveurs nomades du Taïmyr, les réservent aux hôtes de marque ; la peau se retire d'un seul tenant tant que la langue est brûlante, et jamais après.",
     en:"Reindeer tongues poached with juniper berries, pressed and served cold in thin slices. The Dolgans, nomadic herders of Taymyr, keep them for honoured guests; the skin comes off in one piece while the tongue is scalding, and never afterwards."},
  i:[['reindeer_tongue',2,'pc'],['onion',1,'pc'],['carrot',2,'pc'],['juniper_berries',12,'pc'],['bay_leaf',3,'pc'],['black_peppercorns',10,'pc'],['horseradish',60,'g'],['smetana',150,'g'],['rye_bread',300,'g'],['coarse_salt',2,'tbsp']],
  s:{fr:["Faites dégorger les langues 6 heures à l'eau froide, en la changeant deux fois, pour ôter le sang.","Pochez-les 2 h 30 avec l'oignon, la carotte, le genièvre, le laurier et le poivre, à petits frémissements et sans jamais bouillir.","Elles sont prêtes quand une aiguille traverse la base sans résistance : le bout est toujours cuit avant, la base décide.","Sortez-les et pelez-les immédiatement, à l'eau froide sous le robinet — refroidies, la peau adhère et il faut la couper au couteau.","Pressez-les 12 heures au froid sous une planche lestée, puis tranchez très fin en biais. Servez avec un raifort à la smetana et du pain noir."],
     en:["Soak the tongues 6 hours in cold water, changing it twice, to draw out the blood.","Poach them 2½ hours with the onion, carrot, juniper, bay and pepper, at a bare tremble and never boiling.","They are ready when a needle passes through the base without resistance: the tip is always done first, the base decides.","Lift them out and peel them immediately, under cold running water — once cool the skin clings and must be cut away.","Press them 12 hours in the cold under a weighted board, then slice very thinly on the bias. Serve with horseradish smetana and black bread."]} },

{ id:'shangi', c:'eu', lat:64.539, lon:40.518, base:8, prep:120, cook:25, diff:2, tags:['bread','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8dcb8','#c9a878','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Shangi',en:'Shangi'},
  p:{fr:'Arkhangelsk, Russie',en:'Arkhangelsk, Russia'},
  d:{fr:"Des galettes ouvertes de seigle couvertes de purée de pomme de terre et badigeonnées de smetana. Ce sont les ancêtres de la vatrouchka, cuites au four russe du Grand Nord : la garniture ne se met pas dans un puits mais s'étale sur toute la surface, jusqu'au bord.",
     en:"Open rye cakes topped with mashed potato and brushed with smetana. They are the ancestors of the vatrushka, baked in the Russian ovens of the far north: the topping is not set in a well but spread over the whole surface, right to the edge."},
  i:[['rye_flour',300,'g'],['flour',200,'g'],['whole_milk',250,'ml'],['fresh_yeast',15,'g'],['potato',500,'g'],['smetana',200,'g'],['butter',100,'g'],['egg',1,'pc'],['onion',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez les deux farines, le lait tiède, la levure et le sel : la pâte de seigle est collante et lourde, il ne faut pas chercher à la rendre élastique.","Laissez-la lever 1 h 30, elle ne doublera pas — le seigle lève peu, et c'est normal.","Faites une purée ferme, montée au beurre et à un jaune d'œuf, mais sans lait : elle doit se tenir sur la galette sans couler.","Aplatissez des disques de 12 cm, laissez un bourrelet d'un centimètre au pourtour et étalez la purée sur toute la surface.","Badigeonnez généreusement de smetana et cuisez 22 minutes à 220 °C. Beurrez à la sortie, et empilez-les sous un linge pour qu'elles restent souples."],
     en:["Knead both flours, the warm milk, yeast and salt: rye dough is sticky and heavy, and there is no point trying to make it elastic.","Prove it 1½ hours; it will not double — rye rises little, which is normal.","Make a firm mash, beaten with butter and an egg yolk but no milk: it must sit on the cake without running.","Flatten 12 cm discs, leave a one-centimetre rim and spread the mash over the whole surface.","Brush generously with smetana and bake 22 minutes at 220°C. Butter them as they come out, and stack them under a cloth to stay soft."]} },

{ id:'tchoudou-daghestanais', c:'eu', lat:42.975, lon:47.517, base:6, prep:60, cook:25, diff:2, tags:['bread','comfort','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#4f6f3a','#f2dfa8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Tchoudou',en:'Chudu'},
  p:{fr:'Makhatchkala, Daghestan, Russie',en:'Makhachkala, Dagestan, Russia'},
  d:{fr:"Une galette très fine farcie de viande, d'orties ou de courge, cuite à sec puis beurrée. Le Daghestan compte quatorze langues officielles et autant de tchoudou : chaque peuple a le sien, et l'on reconnaît une famille à l'épaisseur qu'elle donne à sa pâte.",
     en:"A very thin flatbread filled with meat, nettles or pumpkin, cooked dry then buttered. Dagestan has fourteen official languages and as many chudu: every people has its own, and a family is known by the thickness it gives its dough."},
  i:[['flour',400,'g'],['kefir',250,'ml'],['ground_lamb',300,'g'],['onion',2,'pc'],['nettles',200,'g'],['butter',100,'g'],['baking_soda',0.5,'tsp'],['black_peppercorns',1,'tsp'],['salt',null,'']],
  s:{fr:["Mêlez le kéfir, le bicarbonate et le sel, attendez la mousse, puis ajoutez la farine et pétrissez brièvement.","Laissez reposer 30 minutes : c'est ce repos, et non le pétrissage, qui rend la pâte assez souple pour s'étirer sans se rompre.","Pour la farce à la viande, mêlez l'agneau cru à l'oignon râpé et à deux cuillerées d'eau ; pour la farce verte, blanchissez les orties trente secondes et pressez-les à fond.","Enfermez la farce dans une boule de pâte, soudez, puis abaissez très doucement jusqu'à 28 cm — on doit deviner la farce par transparence.","Cuisez sur une plaque sèche brûlante, 3 minutes par face, en piquant les cloques. Beurrez généreusement des deux côtés et empilez sous un linge."],
     en:["Mix the kefir, bicarbonate and salt, wait for the foam, then add the flour and knead briefly.","Rest it 30 minutes: it is that rest, not the kneading, that makes the dough supple enough to stretch without tearing.","For the meat filling, mix the raw lamb with grated onion and two spoonfuls of water; for the green one, blanch the nettles thirty seconds and press them thoroughly dry.","Enclose the filling in a ball of dough, seal it, then roll very gently out to 28 cm — the filling should show faintly through.","Cook on a scalding dry griddle, 3 minutes a side, pricking the blisters. Butter generously on both sides and stack under a cloth."]} },

{ id:'pian-se', c:'as', lat:43.125, lon:131.899, base:6, prep:150, cook:30, diff:2, tags:['pork','street','spicy'],
  art:{v:'board',bg:'#33291f',plate:'#f4f0e6',style:'roll',food:['#f4f0e6','#c9402c','#7fae5a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Pian-se',en:'Pyan-se'},
  p:{fr:'Vladivostok, Russie',en:'Vladivostok, Russia'},
  d:{fr:"Une grosse brioche vapeur coréenne farcie de chou pimenté et de porc, vendue dans la rue à Vladivostok. Les Coréens du Primorié l'ont apportée dans les années 1920 ; on la mange debout dans le froid, à trois cents grammes pièce, en la tenant à deux mains pour se réchauffer.",
     en:"A large steamed Korean bun filled with spiced cabbage and pork, sold on the streets of Vladivostok. Primorye Koreans brought it in the 1920s; it is eaten standing in the cold, three hundred grams apiece, held in both hands for the warmth."},
  i:[['flour',600,'g'],['warm_water',330,'ml'],['fresh_yeast',15,'g'],['sugar',2,'tbsp'],['ground_pork',300,'g'],['napa_cabbage',400,'g'],['onion',2,'pc'],['garlic',5,'clove'],['gochugaru',2,'tbsp'],['soy_sauce',40,'ml'],['sesame_oil',15,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée souple avec la farine, l'eau tiède, la levure et le sucre, et laissez lever 1 h 30.","Salez le chou émincé et laissez-le dégorger 40 minutes, puis pressez-le fortement : c'est son eau qui détremperait la brioche.","Mêlez-le au porc cru, à l'oignon, à l'ail, au piment coréen, au soja et à l'huile de sésame, et goûtez une boulette poêlée avant de garnir.","Aplatissez des boules de 100 g, garnissez généreusement et refermez en ramenant les bords au centre, soudure bien pincée dessous.","Laissez pousser 30 minutes sur des carrés de papier, puis cuisez 25 minutes à la vapeur sans jamais découvrir — un courant d'air froid fait retomber la pâte."],
     en:["Knead a soft yeasted dough with the flour, warm water, yeast and sugar, and prove 1½ hours.","Salt the shredded cabbage and let it drain 40 minutes, then press it hard: its water is what would sog the bun.","Mix it with the raw pork, onion, garlic, Korean chilli, soy and sesame oil, and taste a fried patty before filling.","Flatten 100 g balls, fill generously and close by gathering the edges to the centre, seam firmly pinched underneath.","Prove 30 minutes on paper squares, then steam 25 minutes without once lifting the lid — a draught of cold air collapses the dough."]} },

{ id:'kovrizhka-de-siberie', c:'as', lat:52.287, lon:104.281, base:10, prep:40, cook:45, diff:1, tags:['sweet','bake','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'cake',food:['#6f4a2a','#8f6a4a','#c9a878','#e8dcb8'],garnish:'#c9754a'},
  n:{fr:'Kovrijka au miel de taïga',en:'Taiga honey kovrizhka'},
  p:{fr:'Irkoutsk, Sibérie, Russie',en:'Irkutsk, Siberia, Russia'},
  d:{fr:"Un pain d'épices sibérien au seigle et au miel de taïga, plus rustique et plus dense que le pryanik. Il se conservait six mois dans une isba non chauffée ; le miel de taïga, récolté sur les fleurs de l'immense forêt boréale, est presque noir et légèrement amer.",
     en:"A Siberian spice loaf of rye and taiga honey, rougher and denser than the pryanik. It kept six months in an unheated izba; taiga honey, gathered from the flowers of the vast boreal forest, is nearly black and faintly bitter."},
  i:[['rye_flour',350,'g'],['flour',150,'g'],['honey',400,'g'],['sugar',100,'g'],['egg',2,'pc'],['sunflower_oil',80,'ml'],['cinnamon',2,'tsp'],['juniper_berries',8,'pc'],['cloves',0.5,'tsp'],['baking_soda',1,'tsp'],['walnuts',100,'g'],['water',150,'ml'],['salt',null,'']],
  s:{fr:["Faites tiédir le miel avec l'eau sans dépasser 50 °C, puis laissez-le refroidir : chauffé davantage, un miel de taïga perd ce qui le distingue.","Écrasez les baies de genièvre au mortier avec la cannelle et le girofle — c'est le genièvre qui donne à la kovrijka son goût résineux et sibérien.","Mêlez les farines, les épices, le sel et le bicarbonate, puis versez le miel, l'huile et les œufs battus.","La pâte est épaisse et paresseuse : ne la battez pas pour l'alléger, la kovrijka doit rester dense.","Versez dans un moule chemisé sur 4 cm, parsemez de noix et cuisez 45 minutes à 165 °C. Enveloppez-la tiède et attendez trois jours."],
     en:["Warm the honey with the water without going above 50°C, then let it cool: heated further, taiga honey loses what sets it apart.","Crush the juniper berries in a mortar with the cinnamon and cloves — the juniper is what gives a kovrizhka its resinous, Siberian taste.","Mix the flours, spices, salt and bicarbonate, then pour in the honey, oil and beaten eggs.","The batter is thick and sluggish: do not beat it to lighten it, a kovrizhka must stay dense.","Pour into a lined tin 4 cm deep, scatter walnuts and bake 45 minutes at 165°C. Wrap it warm and wait three days."]} },

{ id:'pastilla-de-fes', c:'af', lat:34.034, lon:-5.000, base:8, prep:150, cook:60, diff:3, tags:['poultry','festive','bake'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f4f0e6','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Pastilla de Fès',en:'Fes pastilla'},
  p:{fr:'Fès, Maroc',en:'Fes, Morocco'},
  d:{fr:"Une tourte de feuilles de warqa emplie de pigeon aux amandes et à la cannelle, saupoudrée de sucre glace. Le sucré-salé vient d'al-Andalus, dont les exilés peuplèrent Fès au XVᵉ siècle : la pastilla est le plat andalou qui a survécu au Maroc alors qu'il a disparu d'Espagne.",
     en:"A pie of warqa leaves filled with pigeon, almonds and cinnamon, dusted with icing sugar. The sweet-savoury comes from al-Andalus, whose exiles peopled Fes in the 15th century: pastilla is the Andalusian dish that survived in Morocco after vanishing from Spain."},
  i:[['pigeon',2,'pc'],['warqa_sheets',12,'pc'],['almonds',250,'g'],['egg',8,'pc'],['onion',500,'g'],['cinnamon',2,'tbsp'],['saffron',1,'pinch'],['ginger',1,'tsp'],['cilantro',1,'bunch'],['parsley',1,'bunch'],['butter',150,'g'],['powdered_sugar',80,'g'],['orange_blossom_water',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Braisez les pigeons 1 heure avec l'oignon râpé, le safran, le gingembre et les herbes, puis désossez-les et effilochez la chair.","Faites réduire le jus de cuisson jusqu'à ce qu'il ne reste presque plus de liquide, puis versez-y les œufs battus en remuant sans arrêt.","Les œufs doivent prendre en grumeaux fins et secs : c'est cette couche qui absorbe l'humidité et empêche la warqa de se détremper.","Faites frire les amandes, concassez-les grossièrement et mêlez-les au sucre glace et à la cannelle.","Montez en trois couches — œufs, viande, amandes — entre des feuilles beurrées, cuisez 30 minutes à 200 °C et sucrez en croisillons à la sortie."],
     en:["Braise the pigeons 1 hour with grated onion, saffron, ginger and herbs, then bone them and shred the meat.","Reduce the cooking juices until almost no liquid remains, then pour in the beaten eggs, stirring without pause.","The eggs must set into fine, dry curds: that layer absorbs the moisture and stops the warqa going soggy.","Fry the almonds, chop them roughly and mix them with the icing sugar and cinnamon.","Build three layers — eggs, meat, almonds — between buttered sheets, bake 30 minutes at 200°C and dust in a lattice as it comes out."]} },

{ id:'harira', c:'af', lat:31.630, lon:-7.989, base:8, prep:40, cook:120, diff:2, tags:['legume','soup','slow'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#c9532c','#e0913a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Harira',en:'Harira'},
  p:{fr:'Marrakech, Maroc',en:'Marrakesh, Morocco'},
  d:{fr:"Une soupe de tomate, de lentilles et de pois chiches liée au tadouira, un levain de farine et d'eau fermenté. C'est la soupe de rupture du jeûne pendant le ramadan ; le tadouira se prépare la veille et doit aigrir légèrement, faute de quoi la harira reste sans profondeur.",
     en:"A soup of tomato, lentils and chickpeas thickened with tadouira, a fermented flour-and-water starter. It is the fast-breaking soup of Ramadan; the tadouira is made the day before and must sour slightly, or the harira stays without depth."},
  i:[['lamb_shoulder',300,'g'],['chickpeas',200,'g'],['lentils',150,'g'],['ripe_tomato',800,'g'],['onion',2,'pc'],['celery',3,'pc'],['cilantro',2,'bunch'],['parsley',1,'bunch'],['flour',80,'g'],['ginger',1,'tsp'],['turmeric',1,'tsp'],['cinnamon',1,'tsp'],['smen',2,'tbsp'],['vermicelli',60,'g'],['lemon',2,'pc'],['dates',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Préparez le tadouira la veille : délayez la farine dans deux verres d'eau et laissez fermenter à couvert à température ambiante 24 heures.","Faites revenir l'agneau en dés avec l'oignon, le smen et les épices, ajoutez les pois chiches trempés et couvrez d'eau ; comptez 1 heure.","Mixez la tomate avec la coriandre et le persil et versez-la : jamais concassée, elle doit être liquide et lisse pour se lier au tadouira.","Ajoutez les lentilles et laissez 30 minutes, puis versez le tadouira en filet mince en fouettant sans arrêt.","Versé d'un coup, il forme des grumeaux que rien ne défait. Laissez épaissir 20 minutes, ajoutez les vermicelles et servez avec des dattes et du citron."],
     en:["Make the tadouira the day before: slake the flour in two glasses of water and ferment it covered at room temperature for 24 hours.","Fry the diced lamb with the onion, smen and spices, add the soaked chickpeas and cover with water; allow 1 hour.","Blend the tomato with the coriander and parsley and pour it in: never crushed, it must be liquid and smooth to bind with the tadouira.","Add the lentils and give them 30 minutes, then pour in the tadouira in a thin stream, whisking without pause.","Poured in at once it lumps beyond rescue. Thicken 20 minutes, add the vermicelli and serve with dates and lemon."]} },

{ id:'briouates', c:'af', lat:33.573, lon:-7.590, base:8, prep:90, cook:20, diff:2, tags:['sea','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Briouates',en:'Briouates'},
  p:{fr:'Casablanca, Maroc',en:'Casablanca, Morocco'},
  d:{fr:"De petits triangles de warqa farcis de viande hachée ou de fruits de mer, frits. On les plie comme un drapeau, en repliant la bande sur elle-même en triangles successifs ; le dernier repli se colle à la bouillie de farine, jamais à l'œuf, qui bullerait dans l'huile.",
     en:"Small warqa triangles filled with minced meat or seafood, fried. They are folded like a flag, the strip turned over itself in successive triangles; the last flap is sealed with flour paste, never egg, which would blister in the oil."},
  i:[['warqa_sheets',12,'pc'],['ground_beef',300,'g'],['shrimp',200,'g'],['onion',2,'pc'],['cilantro',1,'bunch'],['parsley',1,'bunch'],['cumin',1,'tbsp'],['sweet_paprika',1,'tsp'],['cheese',100,'g'],['flour',2,'tbsp'],['frying_oil',1,'l'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire la farce jusqu'à ce qu'elle ne rende plus une goutte, et laissez-la refroidir entièrement : une farce tiède ramollit la warqa au pliage.","Découpez les feuilles en bandes de 8 cm et gardez-les sous un linge humide — la warqa sèche et casse en trois minutes à l'air.","Déposez une cuillerée à un bout et repliez en triangle, puis rabattez le triangle sur lui-même jusqu'au bout de la bande.","Scellez le dernier repli avec une bouillie de farine et d'eau, et non à l'œuf.","Frites à 170 °C, 2 minutes par face, six à la fois. Égouttez debout : posés à plat, ils ramollissent par-dessous."],
     en:["Cook the filling until it releases nothing more, and cool it completely: a warm filling softens the warqa as you fold.","Cut the sheets into 8 cm strips and keep them under a damp cloth — warqa dries and cracks within three minutes in the air.","Set a spoonful at one end and fold into a triangle, then keep turning the triangle over itself to the end of the strip.","Seal the last flap with a paste of flour and water, not with egg.","Fry at 170°C, 2 minutes a side, six at a time. Drain upright: laid flat they go soft underneath."]} },

{ id:'zaalouk', c:'af', lat:31.634, lon:-7.999, base:6, prep:30, cook:45, diff:1, tags:['veg','fresh','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'salad',food:['#8f5a3a','#c9532c','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Zaalouk',en:'Zaalouk'},
  p:{fr:'Marrakech, Maroc',en:'Marrakesh, Morocco'},
  d:{fr:"Une salade cuite d'aubergines et de tomates écrasées à l'ail, au cumin et à l'huile d'olive, servie froide. Elle fait partie des salades marocaines qu'on dispose en petits bols avant le plat principal ; les aubergines s'écrasent à la fourchette et jamais au mixeur, qui les rend mousseuses.",
     en:"A cooked salad of aubergine and tomato crushed with garlic, cumin and olive oil, served cold. It is one of the Moroccan salads set out in small bowls before the main dish; the aubergines are crushed with a fork and never blended, which makes them foamy."},
  i:[['eggplant',800,'g'],['ripe_tomato',600,'g'],['garlic',6,'clove'],['cumin',1,'tbsp'],['sweet_paprika',1,'tbsp'],['cilantro',1,'bunch'],['parsley',1,'bunch'],['olive_oil',100,'ml'],['lemon',1,'pc'],['harissa',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites griller les aubergines entières sur la flamme jusqu'à ce que la peau noircisse et que la chair s'affaisse.","Ce grillage direct est ce qui donne le goût fumé : cuites à l'eau ou au four, les aubergines n'ont aucun caractère.","Pelez-les et laissez-les égoutter une demi-heure dans une passoire — leur eau amère délaverait tout le plat.","Faites confire la tomate râpée avec l'ail 25 minutes, jusqu'à ce qu'il ne reste qu'une pâte brique.","Écrasez les aubergines à la fourchette dans la tomate, ajoutez les épices et l'huile, et laissez refroidir. Se mange froid, le lendemain de préférence."],
     en:["Char the whole aubergines over a flame until the skin blackens and the flesh slumps.","That direct charring is what gives the smoky taste: boiled or oven-baked, aubergines have no character at all.","Peel them and let them drain half an hour in a colander — their bitter water would wash out the whole dish.","Cook the grated tomato down with the garlic for 25 minutes, until only a brick-red paste remains.","Crush the aubergines into the tomato with a fork, add the spices and oil, and cool. Eaten cold, preferably the next day."]} },

{ id:'msemen', c:'af', lat:33.590, lon:-7.610, base:8, prep:90, cook:30, diff:3, tags:['bread','breakfast','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Msemen',en:'Msemen'},
  p:{fr:'Casablanca, Maroc',en:'Casablanca, Morocco'},
  d:{fr:"Une crêpe feuilletée carrée, étirée à la main puis repliée avec de la semoule et du beurre, cuite à la plaque. Le feuilletage ne vient pas d'un tourage mais d'un étirement : la pâte est tirée jusqu'à devenir transparente, ce qu'on ne peut faire qu'avec une pâte très huilée.",
     en:"A square layered pancake, hand-stretched then folded with semolina and butter, cooked on a griddle. The layers come not from turning but from stretching: the dough is pulled until transparent, which is only possible with a heavily oiled dough."},
  i:[['flour',400,'g'],['semolina',150,'g'],['warm_water',300,'ml'],['butter',120,'g'],['sunflower_oil',150,'ml'],['honey',100,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la semoule fine, l'eau tiède et le sel quinze minutes : la pâte doit devenir très souple, presque coulante.","Divisez en boules, huilez-les généreusement et laissez-les reposer 30 minutes sous l'huile — c'est elle qui permettra l'étirement.","Étalez chaque boule à plat sur un plan huilé, en tirant du centre vers l'extérieur, jusqu'à voir la main au travers.","Parsemez de beurre fondu et de semoule, puis repliez en trois dans un sens et en trois dans l'autre pour obtenir un carré à neuf épaisseurs.","Aplatissez légèrement et cuisez à la plaque sèche 3 minutes par face, en pressant à la spatule. Servez au miel et au beurre."],
     en:["Knead the flour, fine semolina, warm water and salt for fifteen minutes: the dough must become very supple, almost pourable.","Divide into balls, oil them generously and rest them 30 minutes under the oil — it is what will allow the stretching.","Spread each ball flat on an oiled surface, pulling from the centre outward, until you can see your hand through it.","Scatter melted butter and semolina, then fold in three one way and three the other to make a square of nine layers.","Flatten slightly and cook on a dry griddle 3 minutes a side, pressing with a spatula. Serve with honey and butter."]} },

{ id:'the-a-la-menthe', c:'af', lat:31.626, lon:-7.989, base:6, prep:15, cook:10, diff:2, tags:['drink','fresh','fast'],
  art:{v:'glass',bg:'#28331f',plate:'#f4f0e6',style:'drink',food:['#7fae5a','#e8c46a','#f4f0e6','#4f8f4a'],garnish:'#6fbf8f'},
  n:{fr:'Thé à la menthe',en:'Mint tea'},
  p:{fr:'Marrakech, Maroc',en:'Marrakesh, Morocco'},
  d:{fr:"Du thé vert gunpowder infusé à la menthe et très sucré, versé de haut dans de petits verres. La hauteur du versement n'est pas une coquetterie : elle aère le thé, forme la mousse attendue et refroidit assez le liquide pour qu'on puisse tenir le verre.",
     en:"Gunpowder green tea infused with mint and heavily sweetened, poured from a height into small glasses. The height is no flourish: it aerates the tea, raises the expected foam and cools the liquid enough for the glass to be held."},
  i:[['green_tea',2,'tbsp'],['mint',2,'bunch'],['sugar',120,'g'],['water',1,'l'],['pine_nuts',1,'tbsp']],
  s:{fr:["Ébouillantez le thé une première fois et jetez l'eau au bout de trente secondes : ce rinçage ôte l'amertume et la poussière des feuilles roulées.","Gardez ce premier jus dans un verre à part — les Marocains le réservent et le remettent à la fin, car il contient l'essence du thé.","Versez l'eau bouillante sur les feuilles rincées et laissez infuser trois minutes seulement, sans menthe : le thé infuse seul.","Ajoutez alors la menthe entière, tiges comprises, et le sucre, et laissez deux minutes de plus — la menthe bouillie devient amère.","Versez et reversez trois fois du théière au verre pour mêler, puis servez en tenant la théière à cinquante centimètres."],
     en:["Scald the tea once and throw the water away after thirty seconds: that rinse removes the bitterness and dust from the rolled leaves.","Keep that first liquor in a separate glass — Moroccans set it aside and return it at the end, as it holds the essence of the tea.","Pour boiling water over the rinsed leaves and infuse three minutes only, without mint: the tea infuses alone.","Then add the whole mint, stems and all, and the sugar, and give it two minutes more — boiled mint turns bitter.","Pour back and forth three times between pot and glass to mix, then serve holding the pot fifty centimetres up."]} },

{ id:'chorba-frik', c:'af', lat:36.753, lon:3.059, base:6, prep:30, cook:75, diff:2, tags:['lamb','soup','slow'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#c9532c','#e8dcb8','#7fae5a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Chorba frik',en:'Chorba frik'},
  p:{fr:'Alger, Algérie',en:'Algiers, Algeria'},
  d:{fr:"Une soupe d'agneau au blé vert concassé, à la tomate et à la coriandre, servie chaque soir du ramadan. Le frik est du blé dur récolté vert puis brûlé au feu de paille : cette torréfaction lui donne un goût fumé que le blé mûr n'a pas, et il épaissit sans se déliter.",
     en:"A lamb soup with cracked green wheat, tomato and coriander, served every evening of Ramadan. Frik is durum wheat harvested green then burned over straw: that scorching gives it a smoky taste ripe wheat lacks, and it thickens without disintegrating."},
  i:[['lamb_shoulder',400,'g'],['freekeh',150,'g'],['chickpeas',150,'g'],['ripe_tomato',500,'g'],['onion',2,'pc'],['celery',2,'pc'],['cilantro',2,'bunch'],['mint',1,'bunch'],['cinnamon',1,'stick'],['smen',2,'tbsp'],['tomato_paste',2,'tbsp'],['lemon',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites revenir l'agneau en petits dés dans le smen avec l'oignon râpé et la cannelle, dix minutes, sans coloration forte.","Ajoutez le concentré et la tomate râpée et laissez confire quinze minutes avant de mouiller : c'est ce que les Algériennes appellent faire suer la sauce.","Mouillez d'eau chaude, ajoutez les pois chiches trempés et laissez cuire 45 minutes.","Rincez le frik à grande eau et frottez-le entre les mains : il porte une poussière de balle brûlée qui rendrait la soupe âpre.","Ajoutez-le pour 25 minutes seulement, en remuant souvent car il attache. Terminez par la coriandre, la menthe et un trait de citron."],
     en:["Fry the small-diced lamb in smen with grated onion and cinnamon for ten minutes, without deep colour.","Add the tomato purée and grated tomato and let them cook down fifteen minutes before adding liquid: what Algerian cooks call sweating the sauce.","Moisten with hot water, add the soaked chickpeas and cook 45 minutes.","Rinse the freekeh in plenty of water and rub it between your hands: it carries a dust of burnt chaff that would make the soup harsh.","Add it for 25 minutes only, stirring often as it catches. Finish with coriander, mint and a squeeze of lemon."]} },

{ id:'rechta', c:'af', lat:34.878, lon:-1.315, base:6, prep:120, cook:60, diff:3, tags:['noodles','poultry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#e8dcb8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Rechta',en:'Rechta'},
  p:{fr:'Tlemcen, Algérie',en:'Tlemcen, Algeria'},
  d:{fr:"Des nouilles fraîches cuites à la vapeur, servies dans un bouillon blanc de poulet aux navets et aux pois chiches. C'est le plat des grandes occasions à Alger et Tlemcen ; le bouillon est volontairement pâle, sans tomate ni piment, et la cannelle y remplace le paprika.",
     en:"Fresh noodles steamed and served in a white chicken broth with turnips and chickpeas. It is the dish of great occasions in Algiers and Tlemcen; the broth is deliberately pale, with no tomato and no chilli, and cinnamon takes the place of paprika."},
  i:[['flour',500,'g'],['water',220,'ml'],['chicken',1.2,'kg'],['turnip',400,'g'],['chickpeas',200,'g'],['zucchini',300,'g'],['onion',2,'pc'],['cinnamon',2,'stick'],['smen',3,'tbsp'],['white_pepper',1,'tsp'],['sunflower_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme, laissez-la reposer une heure, puis abaissez-la très fin et roulez la feuille avant de couper des nouilles d'un millimètre.","Séparez-les à la main en les farinant, puis huilez-les légèrement et faites-les cuire à la vapeur trois fois de quinze minutes.","Entre chaque passage, sortez-les, aspergez-les d'eau salée et séparez-les à la fourchette — sans ces trois cuissons elles collent en bloc.","Faites le bouillon avec le poulet, l'oignon, la cannelle et le smen, sans tomate : la rechta se reconnaît à sa couleur pâle.","Ajoutez navets, courgettes et pois chiches pour la dernière demi-heure. Servez les nouilles en dôme, le bouillon versé dessus à table."],
     en:["Knead a firm dough, rest it an hour, then roll it very thin and roll up the sheet before cutting one-millimetre noodles.","Separate them by hand with flour, then oil them lightly and steam them three times for fifteen minutes.","Between each steaming, take them out, sprinkle with salted water and separate them with a fork — without those three cookings they stick in a block.","Make the broth with the chicken, onion, cinnamon and smen, with no tomato: rechta is known by its pale colour.","Add turnips, courgettes and chickpeas for the last half hour. Serve the noodles in a mound, the broth poured over at the table."]} },

{ id:'mhadjeb', c:'af', lat:36.365, lon:6.615, base:6, prep:90, cook:25, diff:3, tags:['veg','street','fry'],
  art:{v:'board',bg:'#33251c',plate:'#f4ead4',style:'flat',food:['#c9532c','#e0b45a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mhadjeb',en:'Mhadjeb'},
  p:{fr:'Constantine, Algérie',en:'Constantine, Algeria'},
  d:{fr:"Une crêpe de semoule étirée jusqu'à la transparence, farcie d'une compotée de tomate et d'oignon, pliée en carré. C'est la nourriture de rue algérienne par excellence ; l'étirement se fait à plat sur une table huilée, et la pâte doit être si fine qu'elle se déchire au moindre à-coup.",
     en:"A semolina pancake stretched until transparent, filled with a tomato and onion compote and folded into a square. It is Algerian street food par excellence; the stretching is done flat on an oiled table, and the dough must be so thin it tears at the least jerk."},
  i:[['semolina',500,'g'],['warm_water',350,'ml'],['ripe_tomato',600,'g'],['onion',400,'g'],['sweet_paprika',1,'tbsp'],['harissa',1,'tsp'],['cumin',1,'tsp'],['sunflower_oil',150,'ml'],['garlic',3,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la semoule fine et l'eau tiède salée vingt minutes : c'est long, mais la semoule ne devient extensible qu'à ce prix.","Huilez les boules et laissez-les reposer une heure sous l'huile, jamais sous un linge — c'est l'huile qui empêche la croûte et permet l'étirement.","Faites confire l'oignon et la tomate 40 minutes jusqu'à obtenir une pâte épaisse, et laissez-la refroidir entièrement.","Étirez chaque boule à plat sur la table huilée, du centre vers les bords, jusqu'à voir le bois au travers.","Déposez la farce au centre, repliez les quatre côtés en carré et cuisez à la plaque sèche 4 minutes par face, en pressant."],
     en:["Knead the fine semolina and warm salted water for twenty minutes: it is long, but semolina becomes extensible only at that price.","Oil the balls and rest them an hour under oil, never under a cloth — the oil prevents a skin and allows the stretching.","Cook the onion and tomato down for 40 minutes to a thick paste, and cool it completely.","Stretch each ball flat on the oiled table, from centre to edge, until you can see the wood through it.","Set the filling in the centre, fold the four sides into a square and cook on a dry griddle 4 minutes a side, pressing down."]} },

{ id:'mtewem', c:'af', lat:36.712, lon:4.045, base:6, prep:60, cook:90, diff:2, tags:['lamb','slow','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#f4f0e6','#e8dcb8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mtewem',en:'Mtewem'},
  p:{fr:'Tizi Ouzou, Kabylie, Algérie',en:'Tizi Ouzou, Kabylia, Algeria'},
  d:{fr:"Des boulettes d'agneau à l'ail mijotées en sauce blanche, avec deux têtes d'ail entières dans la marmite. Mtewem veut dire à l'ail : la moitié de l'ail entre dans les boulettes, l'autre dans la sauce, et c'est un plat qu'on ne sert qu'aux gens que l'on connaît bien.",
     en:"Garlic lamb meatballs simmered in a white sauce, with two whole heads of garlic in the pot. Mtewem means with garlic: half goes into the meatballs, half into the sauce, and it is a dish served only to people one knows well."},
  i:[['ground_lamb',500,'g'],['lamb_shoulder',400,'g'],['garlic',2,'pc'],['cinnamon',1,'tsp'],['egg',2,'pc'],['breadcrumbs',60,'g'],['parsley',1,'bunch'],['chickpeas',200,'g'],['onion',1,'pc'],['smen',2,'tbsp'],['white_pepper',1,'tsp'],['salt',null,'']],
  s:{fr:["Pilez au mortier une tête d'ail entière avec le sel jusqu'à obtenir une crème — hachée au couteau, elle resterait en morceaux durs dans la boulette.","Mêlez-la à l'agneau haché, aux œufs, à la chapelure, à la cannelle et au persil, et laissez reposer une heure au froid.","Faites revenir la viande en morceaux avec l'oignon râpé et le smen, ajoutez la seconde tête d'ail en gousses entières et les pois chiches.","Mouillez d'eau à hauteur et laissez mijoter 45 minutes avant d'y déposer les boulettes, une à une et sans remuer.","Elles cuisent 25 minutes et ne doivent jamais bouillir fort : agitées, elles se défont. La sauce reste blanche, sans une pointe de tomate."],
     en:["Pound a whole head of garlic with salt in a mortar to a cream — chopped by knife it would stay in hard pieces inside the meatball.","Mix it with the minced lamb, eggs, breadcrumbs, cinnamon and parsley, and rest an hour in the cold.","Fry the meat pieces with grated onion and smen, add the second head of garlic in whole cloves and the chickpeas.","Moisten to cover and simmer 45 minutes before lowering the meatballs in, one by one and without stirring.","They cook 25 minutes and must never boil hard: agitated, they fall apart. The sauce stays white, with not a trace of tomato."]} },

{ id:'kalbelouz', c:'af', lat:36.360, lon:6.608, base:12, prep:40, cook:45, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Kalb el louz',en:'Kalb el louz'},
  p:{fr:'Constantine, Algérie',en:'Constantine, Algeria'},
  d:{fr:"Un gâteau de semoule aux amandes noyé de sirop à la fleur d'oranger, servi pendant le ramadan. Le nom veut dire cœur d'amande : la semoule ne se travaille pas mais se laisse reposer, et le sirop se verse froid sur un gâteau brûlant — l'inverse ne fonctionne pas.",
     en:"A semolina and almond cake drowned in orange blossom syrup, served during Ramadan. The name means heart of almond: the semolina is not worked but left to rest, and cold syrup is poured over a scalding cake — the reverse does not work."},
  i:[['semolina',500,'g'],['almonds',200,'g'],['sugar',400,'g'],['butter',150,'g'],['orange_blossom_water',60,'ml'],['water',600,'ml'],['honey',80,'g'],['lemon',1,'pc'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Mêlez la semoule grossière, le beurre fondu, un peu de sucre et l'eau de fleur d'oranger du bout des doigts, sans pétrir.","Laissez reposer 2 heures : la semoule doit gonfler d'elle-même, et une pâte travaillée donne un gâteau caoutchouteux.","Tassez la moitié dans un plat, étalez les amandes mixées au sucre, couvrez du reste et découpez les losanges avant cuisson.","Cuisez 45 minutes à 180 °C, puis versez le sirop froid sur le gâteau brûlant à la sortie du four.","Un sirop chaud sur un gâteau chaud reste en surface : c'est le contraste de température qui le fait pénétrer. Attendez six heures avant de servir."],
     en:["Mix the coarse semolina, melted butter, a little sugar and orange blossom water with your fingertips, without kneading.","Rest it 2 hours: the semolina must swell of its own accord, and a worked dough gives a rubbery cake.","Press half into a dish, spread the almonds blended with sugar, cover with the rest and cut the diamonds before baking.","Bake 45 minutes at 180°C, then pour cold syrup over the scalding cake as it leaves the oven.","Hot syrup on a hot cake stays on the surface: it is the difference in temperature that drives it in. Wait six hours before serving."]} },

{ id:'makroud', c:'af', lat:34.740, lon:10.760, base:12, prep:90, cook:30, diff:3, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9924a','#4f3a2a','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Makroud',en:'Makroud'},
  p:{fr:'Kairouan, Tunisie',en:'Kairouan, Tunisia'},
  d:{fr:"Des losanges de semoule fourrés de pâte de dattes, frits puis trempés dans le miel. Kairouan en a fait sa spécialité et les vend au poids sur la place de la Grande Mosquée ; la pâte ne contient pas d'eau mais seulement de l'huile d'olive, ce qui la rend friable et non élastique.",
     en:"Semolina diamonds filled with date paste, fried then dipped in honey. Kairouan made them its speciality and sells them by weight on the Great Mosque square; the dough holds no water but only olive oil, which makes it short rather than elastic."},
  i:[['semolina',500,'g'],['olive_oil',180,'ml'],['dates',400,'g'],['cinnamon',1,'tsp'],['orange_zest',1,'pc'],['orange_blossom_water',3,'tbsp'],['honey',400,'g'],['frying_oil',1,'l'],['sesame_seeds',2,'tbsp'],['salt',null,'']],
  s:{fr:["Frottez la semoule et l'huile d'olive tiède entre les mains dix minutes, jusqu'à ce que chaque grain soit enrobé, et laissez reposer une heure.","N'ajoutez de l'eau qu'à la toute fin, et le moins possible : une pâte trop hydratée devient élastique et le makroud durcit.","Dénoyautez les dattes, mixez-les avec la cannelle, le zeste et la fleur d'oranger jusqu'à obtenir une pâte souple.","Formez un boudin de pâte, creusez-le en gouttière, garnissez de dattes et refermez, puis aplatissez et coupez en losanges.","Frites à 170 °C jusqu'à ce qu'ils dorent, égouttez, puis plongez-les brûlants dans le miel tiède trois minutes. Égouttez sur grille."],
     en:["Rub the semolina and warm olive oil between your hands for ten minutes, until every grain is coated, and rest it an hour.","Add water only at the very end, and as little as possible: an over-hydrated dough turns elastic and the makroud hardens.","Stone the dates, blend them with the cinnamon, zest and orange blossom water to a supple paste.","Form a rope of dough, hollow it into a channel, fill with dates and close it, then flatten and cut diamonds.","Fry at 170°C until golden, drain, then plunge them scalding into warm honey for three minutes. Drain on a rack."]} },

{ id:'ojja-merguez', c:'af', lat:36.806, lon:10.181, base:4, prep:20, cook:30, diff:1, tags:['spicy','fast','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#c9402c','#e8c46a','#e0913a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Ojja aux merguez',en:'Ojja with merguez'},
  p:{fr:'Tunis, Tunisie',en:'Tunis, Tunisia'},
  d:{fr:"Des œufs pochés dans une sauce tomate à la harissa avec des merguez, servis dans le plat de cuisson. Elle se mange à la cuillère et au pain, directement dans la poêle ; les œufs ne sont pas battus mais cassés entiers, et le jaune doit rester coulant.",
     en:"Eggs poached in a harissa tomato sauce with merguez, served in the cooking pan. It is eaten with a spoon and bread, straight from the pan; the eggs are not beaten but broken in whole, and the yolk must stay runny."},
  i:[['merguez',400,'g'],['egg',6,'pc'],['ripe_tomato',600,'g'],['green_pepper',3,'pc'],['harissa',2,'tbsp'],['garlic',5,'clove'],['tomato_paste',2,'tbsp'],['caraway',1,'tsp'],['coriander_seeds',1,'tsp'],['olive_oil',80,'ml'],['bread',400,'g'],['salt',null,'']],
  s:{fr:["Grillez les poivrons verts sur la flamme, pelez-les et taillez-les en lanières : crus, ils resteraient croquants et déséquilibreraient la sauce.","Faites revenir les merguez, retirez-les et gardez la graisse rouge — c'est elle qui colore la sauce, et non le concentré.","Délayez la harissa et le concentré dans cette graisse et faites-les frire une minute avant d'ajouter la tomate râpée.","Laissez réduire 20 minutes jusqu'à ce que l'huile remonte en surface : c'est le signe que la sauce est prête, exactement comme pour un tajine.","Creusez des puits, cassez les œufs dedans, couvrez et laissez trois minutes seulement. Servez dans la poêle, avec du pain et rien d'autre."],
     en:["Char the green peppers over a flame, peel them and cut them into strips: raw, they would stay crunchy and unbalance the sauce.","Fry the merguez, lift them out and keep the red fat — it, not the tomato purée, is what colours the sauce.","Slake the harissa and purée in that fat and fry them for a minute before adding the grated tomato.","Reduce for 20 minutes until the oil rises to the surface: the sign the sauce is ready, exactly as for a tagine.","Make wells, break the eggs into them, cover and give them three minutes only. Serve in the pan, with bread and nothing else."]} },

{ id:'kamounia', c:'af', lat:33.808, lon:10.845, base:6, prep:30, cook:150, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9532c','#e8dcb8','#6f4a2a'],garnish:'#7fae6a'},
  n:{fr:'Kamounia',en:'Kamounia'},
  p:{fr:'Djerba, Tunisie',en:'Djerba, Tunisia'},
  d:{fr:"Un ragoût de foie ou de bœuf dominé par le cumin, cuit très longtemps jusqu'à une sauce presque noire. Le nom vient de kamoun, le cumin : il en entre trois cuillerées, ce qui paraît excessif jusqu'à ce qu'on comprenne que la longue cuisson en efface l'amertume.",
     en:"A stew of liver or beef dominated by cumin, cooked long into an almost black sauce. The name comes from kamoun, cumin: three spoonfuls go in, which seems excessive until you understand that long cooking removes its bitterness."},
  i:[['beef_chuck',700,'g'],['beef_liver',200,'g'],['cumin',3,'tbsp'],['garlic',8,'clove'],['tomato_paste',2,'tbsp'],['harissa',1,'tbsp'],['olive_oil',100,'ml'],['bay_leaf',2,'pc'],['sweet_paprika',1,'tbsp'],['chickpeas',150,'g'],['bread',400,'g'],['salt',null,'']],
  s:{fr:["Saisissez la viande en cubes dans l'huile d'olive jusqu'à ce qu'elle soit franchement brune, par petites quantités.","Pilez l'ail avec le cumin et le sel au mortier : moulu à sec, le cumin ne libère pas ses huiles et reste poussiéreux.","Faites frire cette pâte trente secondes dans l'huile chaude avant d'ajouter le concentré et la harissa — c'est ce court passage qui ôte le goût cru.","Mouillez d'eau à hauteur et laissez mijoter 2 heures à couvert, jusqu'à ce que la sauce fonce et épaississe.","Ajoutez le foie en dés dans les dix dernières minutes seulement : cuit plus longtemps, il devient granuleux et amer."],
     en:["Sear the diced meat in olive oil until frankly brown, in small batches.","Pound the garlic with the cumin and salt in a mortar: ground dry, cumin does not release its oils and stays dusty.","Fry that paste for thirty seconds in the hot oil before adding the purée and harissa — that brief pass removes the raw taste.","Moisten to cover and simmer 2 hours covered, until the sauce darkens and thickens.","Add the diced liver in the last ten minutes only: cooked longer it turns grainy and bitter."]} },

{ id:'tajine-tunisien', c:'af', lat:36.850, lon:10.320, base:6, prep:40, cook:50, diff:2, tags:['poultry','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#e8c46a','#e0b45a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tajine tunisien',en:'Tunisian tajine'},
  p:{fr:'La Goulette, Tunis, Tunisie',en:'La Goulette, Tunis, Tunisia'},
  d:{fr:"Une omelette épaisse au four, liée au fromage et aux œufs, coupée en carrés comme une frittata. Le mot ne désigne pas ici le plat de terre marocain mais son contraire exact : le tajine tunisien est cuit au four, se mange froid, et se coupe au couteau.",
     en:"A thick baked omelette bound with cheese and eggs, cut into squares like a frittata. Here the word does not mean the Moroccan earthenware dish but its exact opposite: the Tunisian tajine is oven-baked, eaten cold, and cut with a knife."},
  i:[['egg',10,'pc'],['chicken',400,'g'],['onion',2,'pc'],['cheese',200,'g'],['parsley',1,'bunch'],['potato',200,'g'],['turmeric',1,'tsp'],['harissa',1,'tsp'],['breadcrumbs',40,'g'],['olive_oil',60,'ml'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire le poulet avec l'oignon et le curcuma jusqu'à ce qu'il n'y ait plus une goutte de liquide, puis effilochez-le.","Toute humidité résiduelle fait retomber le tajine et l'empêche de se couper : c'est la seule difficulté réelle.","Faites revenir les pommes de terre en petits dés à part, jusqu'à ce qu'elles soient tendres et dorées.","Battez les œufs, ajoutez le fromage râpé, la chapelure, le persil et la harissa, puis toutes les garnitures refroidies.","Versez dans un plat huilé sur 4 cm et cuisez 40 minutes à 180 °C. Laissez refroidir complètement avant de couper en carrés."],
     en:["Cook the chicken with the onion and turmeric until not a drop of liquid remains, then shred it.","Any residual moisture makes the tajine collapse and stops it cutting cleanly: the only real difficulty.","Fry the diced potato separately, until tender and golden.","Beat the eggs, add the grated cheese, breadcrumbs, parsley and harissa, then all the cooled fillings.","Pour into an oiled dish 4 cm deep and bake 40 minutes at 180°C. Cool completely before cutting into squares."]} },

{ id:'bambalouni', c:'af', lat:36.869, lon:10.331, base:8, prep:120, cook:20, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Bambalouni',en:'Bambalouni'},
  p:{fr:'Sidi Bou Saïd, Tunisie',en:'Sidi Bou Saïd, Tunisia'},
  d:{fr:"Un beignet en anneau frit, roulé dans le sucre, vendu brûlant à la sortie de l'huile. On le mange debout devant l'échoppe : il n'existe qu'à cet instant, et un bambalouni de dix minutes n'a plus rien du beignet qu'on est venu chercher.",
     en:"A ring doughnut fried and rolled in sugar, sold scalding as it leaves the oil. It is eaten standing at the stall: it exists only at that moment, and a ten-minute-old bambalouni has nothing left of what you came for."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['warm_water',350,'ml'],['sugar',200,'g'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Délayez la levure dans l'eau tiède et laissez-la mousser, puis battez-la à la farine et au sel — pas de sucre dans la pâte, seulement dessus.","La pâte doit être très molle et collante, presque liquide : on la travaille à la main mouillée, jamais farinée.","Battez-la vigoureusement dix minutes en la soulevant et en la laissant retomber, puis laissez lever 1 h 30.","Prélevez une poignée, percez-la du doigt et étirez l'anneau à la main directement au-dessus de l'huile — un bambalouni ne se façonne jamais à l'avance.","Frites à 180 °C, une minute par face, et roulez dans le sucre immédiatement. Se mange dans les trois minutes."],
     en:["Dissolve the yeast in warm water and let it foam, then beat it into the flour and salt — no sugar in the dough, only on it.","The dough must be very soft and sticky, nearly liquid: it is worked with a wetted hand, never a floured one.","Beat it hard for ten minutes, lifting it and letting it fall back, then prove 1½ hours.","Take a handful, pierce it with a finger and stretch the ring by hand directly over the oil — a bambalouni is never shaped in advance.","Fry at 180°C, one minute a side, and roll in sugar immediately. Eaten within three minutes."]} },

{ id:'mrouzia', c:'af', lat:36.800, lon:10.170, base:6, prep:40, cook:180, diff:2, tags:['lamb','slow','festive'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#c9754a','#e0b45a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Mrouzia',en:'Mrouzia'},
  p:{fr:'Tunis, Tunisie',en:'Tunis, Tunisia'},
  d:{fr:"Un tajine d'agneau au miel, aux raisins secs et au ras el-hanout, très sucré et longuement confit. Il se prépare pour l'Aïd, quand il faut conserver la viande du sacrifice sans réfrigération : le miel et le sel en font une confiture salée qui tient plusieurs semaines.",
     en:"A lamb tagine with honey, raisins and ras el hanout, deeply sweet and long confited. It is made for Eid, when the sacrificial meat must keep without refrigeration: honey and salt turn it into a savoury preserve that lasts weeks."},
  i:[['lamb_shoulder',1.2,'kg'],['honey',200,'g'],['raisins',200,'g'],['almonds',150,'g'],['ras_el_hanout',2,'tbsp'],['cinnamon',2,'stick'],['saffron',1,'pinch'],['onion',2,'pc'],['smen',80,'g'],['ginger',1,'tsp'],['sesame_seeds',2,'tbsp'],['salt',null,'']],
  s:{fr:["Frottez l'agneau de ras el-hanout, de safran et de sel douze heures à l'avance — le mélange doit pénétrer avant toute cuisson.","Faites-le revenir dans le smen avec l'oignon râpé, puis mouillez d'eau à hauteur et laissez mijoter 2 heures à couvert.","Faites gonfler les raisins à part et n'ajoutez le miel que dans la dernière demi-heure : versé au début, il brûlerait au fond de la marmite.","Découvrez et laissez réduire jusqu'à ce que la sauce devienne un sirop épais qui nappe la viande et brille.","Faites frire les amandes séparément et parsemez-les au moment de servir, avec des graines de sésame grillées."],
     en:["Rub the lamb with ras el hanout, saffron and salt twelve hours ahead — the mixture must penetrate before any cooking.","Fry it in smen with the grated onion, then moisten to cover and simmer 2 hours covered.","Plump the raisins separately and add the honey only in the last half hour: poured in at the start it would burn on the base.","Uncover and reduce until the sauce becomes a thick syrup that coats the meat and shines.","Fry the almonds separately and scatter them as you serve, with toasted sesame seeds."]} },

{ id:'shorba-libyenne', c:'af', lat:32.887, lon:13.191, base:6, prep:30, cook:80, diff:1, tags:['lamb','soup','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#c9532c','#e8dcb8','#e0913a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Shorba libyenne',en:'Libyan shorba'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Une soupe d'agneau à la tomate et aux pâtes orzo, très parfumée à la menthe séchée. La menthe s'écrase entre les paumes au-dessus de la marmite juste avant de servir : ajoutée en cours de cuisson, elle perd tout et la soupe devient une soupe de tomate ordinaire.",
     en:"A lamb soup with tomato and orzo pasta, heavily scented with dried mint. The mint is crushed between the palms over the pot just before serving: added during cooking it loses everything and the soup becomes an ordinary tomato soup."},
  i:[['lamb_shoulder',500,'g'],['orzo',150,'g'],['ripe_tomato',400,'g'],['tomato_paste',2,'tbsp'],['onion',2,'pc'],['chickpeas',150,'g'],['dried_mint',2,'tbsp'],['turmeric',1,'tsp'],['cinnamon',1,'tsp'],['sweet_paprika',1,'tbsp'],['parsley',1,'bunch'],['olive_oil',60,'ml'],['lemon',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites revenir l'agneau en petits dés avec l'oignon et les épices sèches, dix minutes, avant d'ajouter la tomate.","Ajoutez le concentré et faites-le frire une minute : cette friture ôte l'acidité métallique du concentré, qu'aucun sucre ne corrigerait ensuite.","Mouillez d'eau chaude, ajoutez les pois chiches et laissez cuire 1 heure à petits frémissements.","Versez l'orzo pour les douze dernières minutes seulement — plus tôt, il boit tout le bouillon et la soupe devient une bouillie.","Écrasez la menthe séchée entre les paumes au-dessus de la marmite, hors du feu, et servez avec beaucoup de citron."],
     en:["Fry the small-diced lamb with the onion and dry spices for ten minutes, before the tomato goes in.","Add the tomato purée and fry it for a minute: that frying removes the metallic acidity no sugar would later correct.","Moisten with hot water, add the chickpeas and cook 1 hour at a bare simmer.","Add the orzo for the last twelve minutes only — any earlier and it drinks the broth and the soup becomes a porridge.","Crush the dried mint between your palms over the pot, off the heat, and serve with plenty of lemon."]} },

{ id:'asida-libyenne', c:'af', lat:32.880, lon:13.187, base:6, prep:20, cook:30, diff:2, tags:['sweet','comfort','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#e8c46a','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Asida',en:'Asida'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Une pâte de farine cuite à l'eau, dressée en dôme et creusée d'un puits de miel et de beurre fondu. Elle se prépare pour la naissance d'un enfant et pour le Mawlid ; on la mange à la main, en pinçant un morceau au bord du dôme et en le trempant dans le puits.",
     en:"A cooked flour paste mounded into a dome and hollowed into a well of honey and melted butter. It is made for the birth of a child and for the Mawlid; it is eaten by hand, pinching a piece from the edge of the dome and dipping it in the well."},
  i:[['flour',400,'g'],['water',900,'ml'],['honey',200,'g'],['butter',150,'g'],['dates',150,'g'],['salt',null,'']],
  s:{fr:["Portez l'eau salée à ébullition et versez la farine d'un seul coup au centre, sans remuer, puis laissez trois minutes.","Cette attente sans remuer est la méthode libyenne : la farine s'hydrate d'elle-même et il se forme moins de grumeaux qu'en fouettant.","Travaillez ensuite à la cuillère de bois vingt minutes, en écrasant contre la paroi : la pâte doit devenir lisse, élastique et se détacher.","Elle est prête quand elle forme un bloc qui suit la cuillère hors de la casserole sans coller.","Dressez en dôme sur un plat, creusez un large puits au centre du poing et emplissez-le de miel tiède et de beurre fondu."],
     en:["Bring salted water to the boil and tip the flour into the centre all at once, without stirring, then leave it three minutes.","That wait without stirring is the Libyan method: the flour hydrates by itself and forms fewer lumps than any whisking.","Then work it with a wooden spoon for twenty minutes, pressing against the sides: the paste must turn smooth, elastic and come away.","It is ready when it forms a block that follows the spoon out of the pan without sticking.","Mound it on a dish, hollow a wide well in the centre with your fist and fill it with warm honey and melted butter."]} },

{ id:'mbatan', c:'af', lat:32.895, lon:13.180, base:6, prep:50, cook:25, diff:2, tags:['veg','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mbatan',en:'Mbatan'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Deux tranches de pomme de terre enfermant une farce de viande épicée, panées et frites. La pomme de terre est coupée en portefeuille, sans traverser : il faut une lame fine et une main sûre, et une tranche fendue jusqu'au bout laisse échapper la farce dans l'huile.",
     en:"Two slices of potato enclosing a spiced meat filling, crumbed and fried. The potato is cut like a wallet, without going through: it needs a thin blade and a steady hand, and a slice cut all the way through spills its filling into the oil."},
  i:[['potato',800,'g'],['ground_beef',300,'g'],['onion',1,'pc'],['parsley',1,'bunch'],['cumin',1,'tsp'],['cinnamon',0.5,'tsp'],['egg',3,'pc'],['flour',100,'g'],['breadcrumbs',150,'g'],['frying_oil',1,'l'],['harissa',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les pommes de terre en tranches de 1 cm, puis fendez chaque tranche en deux dans l'épaisseur en gardant un côté attaché.","Faites-les blanchir trois minutes à l'eau salée et laissez-les refroidir : crues, elles ne cuiraient pas à cœur pendant la friture.","Faites cuire la farce jusqu'à ce qu'elle soit sèche, puis laissez-la refroidir entièrement — chaude, elle ferait glisser la panure.","Garnissez chaque portefeuille sans excès, refermez et pressez du plat de la main pour souder.","Farinez, passez à l'œuf puis à la chapelure, et frites à 175 °C, 4 minutes par face. Servez avec de la harissa et du citron."],
     en:["Cut the potatoes into 1 cm slices, then split each slice through its thickness keeping one side attached.","Blanch them three minutes in salted water and cool them: raw, they would not cook through during frying.","Cook the filling until dry, then cool it completely — warm, it would make the coating slide off.","Fill each wallet without overloading, close it and press with the flat of your hand to seal.","Flour, egg then crumb, and fry at 175°C, 4 minutes a side. Serve with harissa and lemon."]} },

{ id:'ghoriba-libyenne', c:'af', lat:32.885, lon:13.200, base:12, prep:40, cook:20, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#e8dcb8','#f0e8d0','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Ghoriba',en:'Ghoriba'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Un biscuit sablé craquelé, aux amandes ou à la semoule, si friable qu'il fond sans qu'on ait à mâcher. Les craquelures ne sont pas décoratives : elles apparaissent d'elles-mêmes quand la proportion de gras est juste, et un dessus lisse signale une pâte trop hydratée.",
     en:"A cracked shortbread biscuit, with almonds or semolina, so short it dissolves without chewing. The cracks are not decorative: they appear by themselves when the fat is in the right proportion, and a smooth top signals an over-hydrated dough."},
  i:[['ground_almonds',250,'g'],['powdered_sugar',150,'g'],['sunflower_oil',120,'ml'],['egg',2,'pc'],['flour',150,'g'],['baking_powder',1,'tsp'],['sesame_seeds',60,'g'],['orange_blossom_water',2,'tbsp'],['almonds',24,'pc'],['salt',null,'']],
  s:{fr:["Mêlez la poudre d'amande, le sucre glace et l'huile à la main, sans fouetter : la ghoriba se travaille du bout des doigts.","Ajoutez un œuf, la fleur d'oranger, puis la farine et la levure, et arrêtez dès que la pâte se rassemble.","Laissez-la reposer une heure au froid : sans repos, l'huile ressort à la cuisson et les biscuits s'étalent.","Formez des boules et roulez-les dans le sucre glace en couche épaisse — c'est ce sucre qui craquelle et non la pâte elle-même.","Posez une amande au centre et cuisez 18 minutes à 160 °C. Elles doivent rester pâles : dorées, elles sont sèches."],
     en:["Mix the ground almonds, icing sugar and oil by hand, without whisking: a ghoriba is worked with the fingertips.","Add one egg, the orange blossom water, then the flour and baking powder, and stop the moment the dough comes together.","Rest it an hour in the cold: without rest the oil weeps out during baking and the biscuits spread.","Shape balls and roll them in a thick layer of icing sugar — it is that sugar that cracks, not the dough itself.","Press an almond into the centre and bake 18 minutes at 160°C. They must stay pale: browned, they are dry."]} },

{ id:'mhalbiya', c:'af', lat:32.878, lon:13.195, base:6, prep:20, cook:25, diff:1, tags:['sweet','comfort','fresh'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#c9402c','#e8dcb8'],garnish:'#c9754a'},
  n:{fr:'Mhalbiya',en:'Mhalbiya'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Une crème de riz au lait parfumée à l'eau de rose, servie froide et parsemée de pistaches. Elle ne contient ni œuf ni gélatine : c'est l'amidon de riz seul qui la fait prendre, ce qui exige une cuisson lente et une agitation constante pour éviter qu'elle n'attache.",
     en:"A rice-flour milk cream scented with rose water, served cold and scattered with pistachios. It holds neither egg nor gelatine: rice starch alone sets it, which demands slow cooking and constant stirring so it does not catch."},
  i:[['rice_flour',80,'g'],['whole_milk',1,'l'],['sugar',120,'g'],['rose_water',3,'tbsp'],['pistachios',80,'g'],['cinnamon',1,'tsp'],['cornstarch',20,'g'],['almonds',40,'g']],
  s:{fr:["Délayez la farine de riz et la fécule dans un quart du lait froid, jusqu'à ce qu'il ne reste aucun grumeau, puis filtrez.","Portez le reste du lait à frémissement avec le sucre et versez-y le mélange froid en fouettant sans arrêt.","Remuez sans discontinuer vingt minutes à feu doux : la farine de riz attache instantanément et le brûlé traverse tout le plat.","La crème est prête quand elle nappe la cuillère et qu'un sillon tracé au doigt tient trois secondes.","Ajoutez l'eau de rose hors du feu — chauffée, elle s'évapore et ne laisse rien. Versez dans des coupes et laissez prendre 4 heures au froid."],
     en:["Slake the rice flour and cornstarch in a quarter of the cold milk until not a lump remains, then strain.","Bring the rest of the milk to a tremble with the sugar and pour in the cold mixture, whisking without pause.","Stir without stopping for twenty minutes over low heat: rice flour catches instantly and a burnt note carries through the whole dish.","The cream is ready when it coats the spoon and a furrow drawn with a finger holds for three seconds.","Add the rose water off the heat — heated, it evaporates and leaves nothing. Pour into cups and set 4 hours in the cold."]} },

{ id:'ruz-mufalfal', c:'af', lat:32.892, lon:13.176, base:6, prep:30, cook:45, diff:2, tags:['rice','lamb','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e0b45a','#8f5a3a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Ruz mufalfal',en:'Ruz mufalfal'},
  p:{fr:'Tripoli, Libye',en:'Tripoli, Libya'},
  d:{fr:"Un riz aux épices dont chaque grain reste détaché, servi avec de l'agneau et des pignons. Mufalfal veut dire poivré, mais désigne surtout la texture : le riz doit être grain à grain, ce qui s'obtient en le rinçant sept fois et en le faisant nacrer dans le gras avant tout liquide.",
     en:"A spiced rice in which every grain stays separate, served with lamb and pine nuts. Mufalfal means peppered, but really names the texture: the rice must be grain by grain, achieved by rinsing it seven times and pearling it in fat before any liquid."},
  i:[['basmati_rice',400,'g'],['lamb_shoulder',500,'g'],['onion',2,'pc'],['pine_nuts',60,'g'],['raisins',60,'g'],['cinnamon',1,'stick'],['cardamom',4,'pc'],['turmeric',1,'tsp'],['smen',60,'g'],['chicken_broth',700,'ml'],['almonds',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez le riz sept fois jusqu'à ce que l'eau soit parfaitement claire, puis laissez-le tremper 30 minutes et égouttez-le une heure.","Faites revenir l'agneau en dés avec l'oignon et les épices entières dans le smen, puis mouillez et laissez cuire 45 minutes.","Faites nacrer le riz égoutté dans le gras deux minutes avant tout liquide : cet enrobage isole chaque grain et l'empêche de coller.","Versez le bouillon dans la proportion exacte d'un volume et demi pour un de riz, portez à ébullition, couvrez et baissez au minimum.","Douze minutes, puis dix minutes hors du feu sans découvrir. Aérez à la fourchette et couronnez de pignons et d'amandes frits."],
     en:["Rinse the rice seven times until the water runs perfectly clear, then soak it 30 minutes and drain it for an hour.","Fry the diced lamb with the onion and whole spices in smen, then moisten and cook 45 minutes.","Pearl the drained rice in the fat for two minutes before any liquid: that coating isolates each grain and stops it sticking.","Pour in broth at exactly one and a half volumes to one of rice, bring to the boil, cover and drop to the lowest heat.","Twelve minutes, then ten minutes off the heat without uncovering. Fluff with a fork and crown with fried pine nuts and almonds."]} },

{ id:'tamiya', c:'af', lat:30.048, lon:31.244, base:6, prep:750, cook:20, diff:2, tags:['legume','fry','street'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#7fae5a','#c9924a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Ta‘miya',en:'Ta‘miya'},
  p:{fr:'Le Caire, Égypte',en:'Cairo, Egypt'},
  d:{fr:"Le falafel égyptien, fait de fèves sèches et non de pois chiches, vert à cœur et couvert de sésame. Les fèves donnent une texture bien plus légère et humide que le pois chiche ; l'Égypte revendique l'antériorité, et les coptes en faisaient déjà pendant le carême.",
     en:"The Egyptian falafel, made from dried broad beans rather than chickpeas, green inside and coated in sesame. Broad beans give a far lighter, moister texture than chickpeas; Egypt claims the older version, and Copts were making it during Lent."},
  i:[['broad_beans',500,'g'],['cilantro',2,'bunch'],['parsley',1,'bunch'],['spring_onion',6,'pc'],['garlic',8,'clove'],['cumin',1,'tbsp'],['coriander_seeds',1,'tbsp'],['baking_soda',1,'tsp'],['sesame_seeds',80,'g'],['frying_oil',1.5,'l'],['pita_bread',6,'pc'],['tahini',100,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les fèves décortiquées 12 heures et ne les cuisez sous aucun prétexte : le falafel se fait avec des légumineuses crues, et des fèves cuites donnent une bouillie qui se défait dans l'huile.","Passez-les au hachoir avec les herbes et l'ail deux fois, en gardant du grain — un mixeur les réduirait en pâte lisse et compacte.","Salez et ajoutez le bicarbonate seulement au moment de frire : ajouté plus tôt, il fait rendre l'eau à la pâte.","Formez des galettes plates de 5 cm et pressez une face dans le sésame, sans en couvrir les deux.","Frites à 175 °C, trois minutes par face. L'intérieur doit rester vert vif et humide ; un cœur brun signifie que la pâte a attendu trop longtemps."],
     en:["Soak the skinned broad beans 12 hours and on no account cook them: falafel is made with raw pulses, and cooked beans give a mush that falls apart in the oil.","Mince them with the herbs and garlic twice, keeping some grain — a blender would reduce them to a smooth, dense paste.","Salt and add the bicarbonate only as you fry: added earlier, it makes the mixture weep.","Shape flat 5 cm patties and press one face into the sesame, not both.","Fry at 175°C, three minutes a side. The inside must stay bright green and moist; a brown centre means the mixture waited too long."]} },

{ id:'mahshi', c:'af', lat:30.052, lon:31.230, base:6, prep:90, cook:90, diff:2, tags:['veg','slow','festive'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'other',food:['#7fae5a','#c9532c','#e8dcb8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Mahshi',en:'Mahshi'},
  p:{fr:'Le Caire, Égypte',en:'Cairo, Egypt'},
  d:{fr:"Des légumes évidés et des feuilles de vigne farcis de riz aux herbes, cuits serrés dans une marmite. Le riz est mis cru et gonfle de moitié : c'est pourquoi on ne remplit jamais qu'aux deux tiers, et un mahshi trop garni éclate et vide sa farce dans le bouillon.",
     en:"Hollowed vegetables and vine leaves stuffed with herbed rice, packed tight in a pot. The rice goes in raw and swells by half: which is why they are never filled more than two-thirds, and an overfilled mahshi bursts and empties into the broth."},
  i:[['zucchini',6,'pc'],['eggplant',4,'pc'],['grape_leaves',30,'pc'],['red_pepper',4,'pc'],['long_grain_rice',400,'g'],['ripe_tomato',400,'g'],['onion',2,'pc'],['dill',2,'bunch'],['parsley',2,'bunch'],['cilantro',1,'bunch'],['tomato_paste',2,'tbsp'],['smen',80,'g'],['lemon',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Évidez les courgettes et les aubergines à la cuillère spéciale en laissant cinq millimètres de paroi : plus fin, le légume s'effondre.","Rincez le riz et mêlez-le cru à la tomate râpée, à l'oignon, aux herbes hachées et au smen fondu, sans le cuire.","Emplissez aux deux tiers seulement et tassez à peine — le riz doit avoir la place de gonfler.","Tapissez le fond de la marmite de tranches de tomate et rangez les légumes debout et serrés, de sorte qu'ils se soutiennent.","Posez une assiette dessus pour les maintenir, mouillez à mi-hauteur et laissez frémir 1 h 15 sans jamais remuer. Citron au moment de servir."],
     en:["Hollow the courgettes and aubergines with a corer leaving five millimetres of wall: any thinner and the vegetable collapses.","Rinse the rice and mix it raw with grated tomato, onion, chopped herbs and melted smen, without cooking it.","Fill only two-thirds and press barely — the rice must have room to swell.","Line the base of the pot with tomato slices and pack the vegetables upright and tight, so they hold each other up.","Set a plate on top to keep them down, add liquid to half their height and simmer 1¼ hours without ever stirring. Lemon on serving."]} },

{ id:'fattah', c:'af', lat:30.040, lon:31.250, base:6, prep:40, cook:150, diff:2, tags:['lamb','rice','festive'],
  art:{v:'plate',bg:'#33251c',plate:'#f0e4c8',style:'rice',food:['#e8dcb8','#8f5a3a','#c9532c','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Fattah',en:'Fattah'},
  p:{fr:'Le Caire, Égypte',en:'Cairo, Egypt'},
  d:{fr:"Des couches de pain frit, de riz et de viande arrosées d'un bouillon à l'ail et au vinaigre. C'est le plat de l'Aïd el-Adha, préparé avec la viande du sacrifice ; le pain rassis du fond doit rester croustillant par endroits et détrempé par d'autres, et c'est ce contraste qu'on cherche.",
     en:"Layers of fried bread, rice and meat doused with a garlic and vinegar broth. It is the dish of Eid al-Adha, made with the sacrificial meat; the stale bread at the bottom must stay crisp in places and soaked in others, and that contrast is the point."},
  i:[['lamb_shoulder',1,'kg'],['pita_bread',6,'pc'],['long_grain_rice',400,'g'],['garlic',10,'clove'],['white_vinegar',80,'ml'],['tomato_paste',3,'tbsp'],['smen',80,'g'],['cardamom',4,'pc'],['bay_leaf',2,'pc'],['onion',1,'pc'],['vermicelli',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez l'agneau 2 heures avec l'oignon, la cardamome et le laurier, en écumant, et gardez le bouillon.","Coupez le pain rassis en carrés et faites-les frire ou griller jusqu'à ce qu'ils soient bruns et durs : un pain mou se transformerait en pâte.","Faites un riz aux vermicelles grillés dans le smen, mouillé du bouillon d'agneau.","Préparez la sauce en faisant frire l'ail pilé dans le smen jusqu'à ce qu'il dore, puis ajoutez le vinaigre et le concentré, et retirez du feu aussitôt.","Montez : pain au fond, bouillon versé dessus, riz, viande, puis la sauce à l'ail. Servez sans attendre, avant que tout le pain n'ait ramolli."],
     en:["Poach the lamb 2 hours with the onion, cardamom and bay, skimming, and keep the broth.","Cut the stale bread into squares and fry or toast them until brown and hard: soft bread would turn to paste.","Make a rice with vermicelli toasted in smen, moistened with the lamb broth.","Make the sauce by frying pounded garlic in smen until golden, then add the vinegar and tomato purée, and take it off the heat at once.","Build: bread at the bottom, broth poured over, rice, meat, then the garlic sauce. Serve immediately, before all the bread has softened."]} },

{ id:'rozz-bil-laban', c:'af', lat:30.036, lon:31.240, base:6, prep:20, cook:60, diff:1, tags:['sweet','rice','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Rozz bil laban',en:'Rozz bil laban'},
  p:{fr:'Le Caire, Égypte',en:'Cairo, Egypt'},
  d:{fr:"Un riz au lait très crémeux, gratiné au four jusqu'à former une peau brune. Le riz est d'abord cuit à l'eau puis longuement au lait : le cuire directement au lait le laisserait dur au centre, car le sucre et le calcium du lait durcissent l'amidon.",
     en:"A very creamy rice pudding, browned in the oven until a skin forms. The rice is first cooked in water then long in milk: cooked straight in milk it would stay hard at the centre, because milk sugars and calcium toughen the starch."},
  i:[['long_grain_rice',200,'g'],['whole_milk',1.5,'l'],['sugar',180,'g'],['heavy_cream',200,'ml'],['cornstarch',20,'g'],['vanilla',1,'pc'],['rose_water',2,'tbsp'],['pistachios',60,'g'],['cinnamon',1,'tsp'],['water',400,'ml'],['salt',null,'']],
  s:{fr:["Faites d'abord cuire le riz à l'eau 15 minutes, jusqu'à ce qu'il soit tendre mais entier, et égouttez-le.","Ajoutez le lait chaud et laissez cuire 40 minutes à feu très doux, en remuant toutes les cinq minutes.","Ne sucrez qu'à mi-cuisson : le sucre ajouté trop tôt empêche l'amidon de gonfler et le riz reste ferme.","Liez à la fécule délayée dans un peu de lait froid, ajoutez la crème et la vanille, et parfumez à l'eau de rose hors du feu.","Versez dans un plat et passez cinq minutes sous le gril pour former la peau brune. Se mange tiède ou froid, jamais brûlant."],
     en:["First cook the rice in water for 15 minutes, until tender but whole, and drain it.","Add the hot milk and cook 40 minutes over very low heat, stirring every five minutes.","Sweeten only halfway through: sugar added too early stops the starch swelling and the rice stays firm.","Thicken with cornstarch slaked in a little cold milk, add the cream and vanilla, and scent with rose water off the heat.","Pour into a dish and give it five minutes under the grill to form the brown skin. Eaten warm or cold, never scalding."]} },

{ id:'umm-ali', c:'af', lat:30.056, lon:31.228, base:8, prep:25, cook:35, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#f4f0e6','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Umm Ali',en:'Umm Ali'},
  p:{fr:'Le Caire, Égypte',en:'Cairo, Egypt'},
  d:{fr:"Un gratin de pâte feuilletée émiettée, de lait, de noix et de raisins, doré au four. La légende l'attribue à Chajar ad-Durr, sultane du XIIIᵉ siècle, qui l'aurait fait distribuer pour célébrer la mort d'une rivale ; l'histoire est douteuse, le dessert ne l'est pas.",
     en:"A gratin of crumbled puff pastry, milk, nuts and raisins, browned in the oven. Legend attributes it to Shajar al-Durr, a 13th-century sultana, who is said to have had it distributed to celebrate a rival's death; the story is doubtful, the pudding is not."},
  i:[['puff_pastry',400,'g'],['whole_milk',800,'ml'],['heavy_cream',300,'ml'],['sugar',150,'g'],['pistachios',60,'g'],['almonds',60,'g'],['walnuts',60,'g'],['raisins',80,'g'],['coconut',40,'g'],['cinnamon',1,'tsp'],['vanilla',1,'pc']],
  s:{fr:["Cuisez la pâte feuilletée à plat jusqu'à ce qu'elle soit très dorée et sèche, puis laissez-la refroidir et émiettez-la à la main.","Une pâte pâle ou molle se transformerait en colle : elle doit être franchement cuite avant d'aller dans le lait.","Faites chauffer le lait avec le sucre et la vanille sans bouillir, et faites gonfler les raisins dedans dix minutes.","Mêlez le feuilletage émietté aux fruits secs concassés dans un plat, versez le lait chaud dessus et laissez absorber cinq minutes.","Nappez de crème fouettée non sucrée et passez 25 minutes à 200 °C, jusqu'à ce que le dessus soit brun et boursouflé. Servez brûlant."],
     en:["Bake the puff pastry flat until deeply golden and dry, then cool it and crumble it by hand.","Pale or soft pastry would turn to glue: it must be frankly baked before it meets the milk.","Heat the milk with the sugar and vanilla without boiling, and plump the raisins in it for ten minutes.","Mix the crumbled pastry with the chopped nuts in a dish, pour the hot milk over and let it absorb for five minutes.","Cover with unsweetened whipped cream and give it 25 minutes at 200°C, until the top is brown and blistered. Serve scalding."]} },

{ id:'mhadjeb-au-fromage', c:'af', lat:36.370, lon:6.600, base:6, prep:90, cook:25, diff:3, tags:['cheese','street','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#e0b45a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mhadjeb au fromage',en:'Cheese mhadjeb'},
  p:{fr:'Constantine, Algérie',en:'Constantine, Algeria'},
  d:{fr:"La version au fromage fondu du mhadjeb constantinois, plus récente et devenue la plus vendue dans la rue. Le fromage remplace la compotée de tomate mais impose une contrainte nouvelle : il fond et cherche à sortir, ce qui oblige à souder les quatre côtés en pinçant fermement.",
     en:"The melted cheese version of the Constantine mhadjeb, more recent and now the biggest street seller. The cheese replaces the tomato compote but brings a new constraint: it melts and tries to escape, which means sealing all four sides with a firm pinch."},
  i:[['semolina',500,'g'],['warm_water',350,'ml'],['processed_cheese',300,'g'],['onion',2,'pc'],['harissa',1,'tsp'],['sweet_paprika',1,'tsp'],['sunflower_oil',150,'ml'],['parsley',1,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la semoule fine et l'eau tiède salée vingt minutes, jusqu'à ce que la pâte devienne lisse et très souple.","Divisez en boules, couvrez-les d'huile et laissez reposer une heure : sans cette immersion, l'étirement est impossible.","Faites fondre l'oignon 30 minutes avec le paprika et la harissa, laissez refroidir, puis mêlez-le au fromage coupé en dés.","Étirez la pâte à plat sur la table huilée jusqu'à la transparence, garnissez le centre et repliez les quatre côtés en pinçant chaque soudure.","Cuisez à la plaque sèche 4 minutes par face en pressant : le fromage doit fondre entièrement sans jamais s'échapper."],
     en:["Knead the fine semolina and warm salted water for twenty minutes, until the dough turns smooth and very supple.","Divide into balls, cover them with oil and rest an hour: without that immersion the stretching is impossible.","Melt the onion for 30 minutes with the paprika and harissa, cool it, then mix it with the diced cheese.","Stretch the dough flat on an oiled table until transparent, fill the centre and fold the four sides in, pinching each seam.","Cook on a dry griddle 4 minutes a side, pressing down: the cheese must melt entirely without ever escaping."]} }
];
